PAYLOADS = {'backend/app/backtest/fvg/__init__.py': '', 'backend/app/backtest/fvg/fvg_v1_engine.py': '# backend/app/backtest/fvg/fvg_v1_engine.py\n#\n# ── FVG_V1 ("Fissure") ENGINE ── Fair Value Gap / Inverse FVG pullback\n# entries on NIFTY SPOT for weekly option BUYING. PURE MODULE: no DB, no\n# clock, no I/O — every decision is made from closed bars, so a live engine\n# can re-run it incrementally (parity-by-construction, as STFC/ORB/VET).\n#\n# Fence: FVG_V1_20260916\n# LAB PARITY: this file is the lab engine (tools/lab/fvg/fvg_fib_engine.py,\n# fence FVG_LAB_20260916) with only this header changed. The runner test\n# replays a synthetic corpus through BOTH runners when the lab is present\n# and demands identical trades. Never edit one without the other.\n#\n# ── THE IDEA ──────────────────────────────────────────────────────────────\n#   A Fair Value Gap is a 3-candle displacement: candle[i].low > candle[i-2]\n#   .high (bullish) leaves an un-traded price band [c[i-2].high, c[i].low].\n#   The thesis (ICT school): the impulse that left the gap is institutional\n#   participation; price tends to return INTO the gap ("fill the imbalance")\n#   and continue in the impulse direction. We do NOT buy the gap blindly —\n#   we wait for price to (a) come back into the band and (b) print a 1m\n#   rejection close back above the band. That converts a "level" into a\n#   "confirmed level", which is where the option is bought.\n#\n#   Inverse FVG (IFVG): a gap that is VIOLATED by a tf-bar close through it\n#   flips polarity — old bullish gap becomes a bearish supply band. We trade\n#   the retest of the inverted band in the new direction.\n#\n#   Fibonacci gate (FVG setups only): the gap must sit inside the 0.382–0.786\n#   retracement of the impulse leg (swing extreme before the displacement →\n#   impulse extreme). A gap outside that band is either too shallow (weak\n#   displacement) or too deep (the leg already failed).\n#\n# ── DECISIONS (D1–D7, locked before the runner) ───────────────────────────\n#   D1  Signal timeframe `tf` (default 5m) built from 1m SPOT, session grid\n#       09:15. FVG detection and inversion are decided on CLOSED tf bars.\n#   D2  Displacement filter: the middle candle body >= disp_atr × ATR(tf)\n#       and the gap width >= gap_min_atr × ATR. ATR is Wilder RMA over\n#       `atr_len` tf bars and is CONTINUOUS across sessions (warm-up needed).\n#   D3  Trigger on 1m bars only AFTER the gap\'s birth bar has closed:\n#         bull FVG:  touched when 1m low <= top; trigger when touched AND\n#                    1m close > top AND close > open (rejection candle).\n#         bear FVG:  mirror.\n#         IFVG (inverted bull → bearish band): touched when 1m high >= bottom;\n#                    trigger when touched AND 1m close < bottom AND close < open.\n#       Entry is at the NEXT 1m open (runner). A gap is used at most once.\n#   D4  Structural stop: bull FVG stop = gap bottom − buf; bear = top + buf;\n#       IFVG stops on the far side of the band. buf = sl_buf_atr × ATR.\n#   D5  Inversion: bull gap inverts on a tf CLOSE below its bottom; an\n#       inverted band dies on a tf close back through its far side. Gaps\n#       expire `gap_max_age` tf bars after birth (or after inversion).\n#   D6  Gaps are INTRADAY only (list cleared at day start). Cross-day gaps\n#       are a separate hypothesis; not in v1.\n#   D7  Fib gate applies to FVG setups; IFVG has no clean impulse leg and\n#       is exempt (explicitly counted so the share is visible).\n#\n# ── FALSIFICATION TRIPWIRES (runner prints all of these) ──────────────────\n#   * sl_fill_artifact: net(SL fills at option low) vs net(SL at close) —\n#     P&L must not be a fill-convention artifact (ORB_SLFILL doctrine).\n#   * time/eod share of net: if the timed exit carries the net the edge is\n#     "hold after a gap", not the level.\n#   * FVG vs IFVG net, CE vs PE net, per-year signs, per-hour, per-DTE.\n#   * sl_in_entry_minute: stops hit in the fill minute = noise stop (STFC scar).\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Optional\n\nSESSION_OPEN_MIN = 9 * 60 + 15         # 09:15 IST, minute-of-day\nIST_OFFSET = 5 * 3600 + 30 * 60\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  BARS\n# ─────────────────────────────────────────────────────────────────────────\n@dataclass\nclass Bar:\n    ts: int\n    open: float\n    high: float\n    low: float\n    close: float\n    end_min: int = 0                   # tf bars: last minute-of-day inside the bar\n    start_min: int = 0\n\n\ndef resample_session(bars_1m: List[Bar], *, day_start_epoch: int,\n                     tf_minutes: int) -> List[Bar]:\n    """Bucket 1m bars onto the 09:15 grid (identical to the STFC helper)."""\n    out: Dict[int, dict] = {}\n    for b in bars_1m:\n        mod = (b.ts - day_start_epoch) // 60\n        if mod < SESSION_OPEN_MIN:\n            continue\n        bucket = (mod - SESSION_OPEN_MIN) // tf_minutes\n        bts = day_start_epoch + (SESSION_OPEN_MIN + bucket * tf_minutes) * 60\n        cur = out.get(bts)\n        if cur is None:\n            out[bts] = {"o": b.open, "h": b.high, "l": b.low, "c": b.close,\n                        "s": SESSION_OPEN_MIN + bucket * tf_minutes,\n                        "e": SESSION_OPEN_MIN + (bucket + 1) * tf_minutes - 1}\n        else:\n            cur["h"] = max(cur["h"], b.high)\n            cur["l"] = min(cur["l"], b.low)\n            cur["c"] = b.close\n    return [Bar(ts, v["o"], v["h"], v["l"], v["c"], v["e"], v["s"])\n            for ts, v in sorted(out.items())]\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  ATR — Wilder RMA, stateful, continuous across sessions\n# ─────────────────────────────────────────────────────────────────────────\nclass ATR:\n    def __init__(self, length: int):\n        if length < 1:\n            raise ValueError("atr length must be >= 1")\n        self.length = int(length)\n        self.n = 0\n        self.tr_sum = 0.0\n        self.value: Optional[float] = None\n        self.prev_close: Optional[float] = None\n\n    def update(self, b: Bar) -> Optional[float]:\n        tr = (b.high - b.low) if self.prev_close is None else max(\n            b.high - b.low, abs(b.high - self.prev_close), abs(b.low - self.prev_close))\n        if self.n < self.length - 1:\n            self.tr_sum += tr\n        elif self.n == self.length - 1:\n            self.tr_sum += tr\n            self.value = self.tr_sum / self.length\n        else:\n            self.value = (self.value * (self.length - 1) + tr) / self.length\n        self.n += 1\n        self.prev_close = b.close\n        return self.value\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  GAPS\n# ─────────────────────────────────────────────────────────────────────────\n@dataclass\nclass Gap:\n    side: str                          # \'BULL\' | \'BEAR\'   (polarity NOW)\n    top: float\n    bottom: float\n    born_idx: int                      # tf index of the third candle\n    born_end_min: int\n    atr_at_birth: float\n    leg_low: float\n    leg_high: float\n    fib_ok: bool\n    state: str = "FRESH"               # FRESH | INVERTED | DEAD\n    age: int = 0                       # tf bars since birth / inversion\n    touched: bool = False\n    used: bool = False\n    inverted_from: Optional[str] = None\n    gid: int = 0\n\n    @property\n    def kind(self) -> str:\n        return "IFVG" if self.state == "INVERTED" else "FVG"\n\n\n@dataclass(frozen=True)\nclass Signal:\n    trigger_min: int                   # minute-of-day of the rejection close\n    side: str                          # \'CE\' | \'PE\'\n    kind: str                          # \'FVG\' | \'IFVG\'\n    sl_level: float                    # structural stop on SPOT\n    zone_top: float\n    zone_bottom: float\n    leg_target: Optional[float]        # fib 1.0 target (FVG only) else None\n    atr: float\n    gid: int\n\n\n@dataclass\nclass EngineConfig:\n    atr_len: int = 14\n    disp_atr: float = 1.0              # middle-candle body >= disp_atr × ATR\n    gap_min_atr: float = 0.15          # gap width >= gap_min_atr × ATR\n    fib_gate: bool = True\n    fib_lo: float = 0.382\n    fib_hi: float = 0.786\n    fib_lookback: int = 10             # tf bars before the displacement candle\n    sl_buf_atr: float = 0.10\n    gap_max_age: int = 12              # tf bars (12 × 5m = 60 min)\n    trade_fvg: bool = True\n    trade_ifvg: bool = True\n    direction: str = "BOTH"            # BOTH | CE | PE\n    max_gaps: int = 6                  # newest gaps kept per day\n\n\ndef _fib_overlap(cfg: EngineConfig, side: str, zone_top: float,\n                 zone_bottom: float, leg_low: float, leg_high: float) -> bool:\n    rng = leg_high - leg_low\n    if rng <= 0:\n        return False\n    if side == "BULL":\n        hi_px = leg_high - cfg.fib_lo * rng    # shallower retrace (higher price)\n        lo_px = leg_high - cfg.fib_hi * rng    # deeper retrace\n    else:\n        lo_px = leg_low + cfg.fib_lo * rng\n        hi_px = leg_low + cfg.fib_hi * rng\n    return zone_top >= lo_px and zone_bottom <= hi_px\n\n\nclass FvgEngine:\n    """Per-day setup machine. Call new_day() at the start of every session,\n    on_tf_close() after every closed tf bar, on_minute() for every 1m bar\n    that lies AFTER the tf bar it belongs to has been born (the runner\n    guarantees ordering — see runner R1)."""\n\n    def __init__(self, cfg: EngineConfig, atr: ATR):\n        self.cfg = cfg\n        self.atr = atr\n        self.gaps: List[Gap] = []\n        self.bars: List[Bar] = []\n        self._gid = 0\n        self.diag: Dict[str, int] = {}\n\n    # ── diagnostics ──\n    def _bump(self, k: str, n: int = 1) -> None:\n        self.diag[k] = self.diag.get(k, 0) + n\n\n    def new_day(self) -> None:\n        self.gaps = []\n        self.bars = []\n\n    # ── tf bar closed ──\n    def on_tf_close(self, b: Bar) -> None:\n        self.bars.append(b)\n        atr = self.atr.update(b)\n        i = len(self.bars) - 1\n        # 1. age / inversion / death of existing gaps\n        for g in self.gaps:\n            if g.state == "DEAD":\n                continue\n            g.age += 1\n            if g.age > self.cfg.gap_max_age:\n                g.state = "DEAD"\n                self._bump("gap_expired")\n                continue\n            if g.state == "FRESH":\n                if (g.side == "BULL" and b.close < g.bottom) or \\\n                   (g.side == "BEAR" and b.close > g.top):\n                    g.state = "INVERTED"\n                    g.inverted_from = g.side\n                    g.side = "BEAR" if g.side == "BULL" else "BULL"\n                    g.age = 0\n                    g.touched = False\n                    g.used = False\n                    self._bump("gap_inverted")\n            elif g.state == "INVERTED":\n                # reclaimed through the far side → band is spent\n                if (g.side == "BEAR" and b.close > g.top) or \\\n                   (g.side == "BULL" and b.close < g.bottom):\n                    g.state = "DEAD"\n                    self._bump("ifvg_reclaimed")\n        # 2. detect a new gap on the last three closed bars\n        if atr is None or i < 2:\n            return\n        c0, c1, c2 = self.bars[i - 2], self.bars[i - 1], self.bars[i]\n        body = abs(c1.close - c1.open)\n        side = None\n        if c2.low > c0.high and c1.close > c1.open:\n            side, top, bottom = "BULL", c2.low, c0.high\n        elif c2.high < c0.low and c1.close < c1.open:\n            side, top, bottom = "BEAR", c0.low, c2.high\n        if side is None:\n            return\n        self._bump("gap_raw")\n        if body < self.cfg.disp_atr * atr:\n            self._bump("gap_rej_displacement")\n            return\n        if (top - bottom) < self.cfg.gap_min_atr * atr:\n            self._bump("gap_rej_width")\n            return\n        lb = max(0, i - 1 - self.cfg.fib_lookback)\n        seg = self.bars[lb:i - 1] or [c1]\n        if side == "BULL":\n            leg_low = min(x.low for x in seg + [c1])\n            leg_high = max(c1.high, c2.high)\n        else:\n            leg_high = max(x.high for x in seg + [c1])\n            leg_low = min(c1.low, c2.low)\n        fib_ok = _fib_overlap(self.cfg, side, top, bottom, leg_low, leg_high)\n        self._bump("gap_fib_ok" if fib_ok else "gap_fib_reject")\n        self._gid += 1\n        g = Gap(side=side, top=top, bottom=bottom, born_idx=i,\n                born_end_min=c2.end_min, atr_at_birth=atr,\n                leg_low=leg_low, leg_high=leg_high, fib_ok=fib_ok, gid=self._gid)\n        self.gaps.append(g)\n        self._bump("gap_born_bull" if side == "BULL" else "gap_born_bear")\n        live = [x for x in self.gaps if x.state != "DEAD"]\n        if len(live) > self.cfg.max_gaps:\n            for x in live[:-self.cfg.max_gaps]:\n                x.state = "DEAD"\n                self._bump("gap_evicted")\n\n    # ── 1m bar (after its tf bar\'s predecessors have closed) ──\n    def on_minute(self, m: Bar, mod: int) -> Optional[Signal]:\n        cfg = self.cfg\n        for g in self.gaps:\n            if g.state == "DEAD" or g.used or g.born_end_min >= mod:\n                continue\n            is_ifvg = g.state == "INVERTED"\n            if is_ifvg and not cfg.trade_ifvg:\n                continue\n            if not is_ifvg and not cfg.trade_fvg:\n                continue\n            if not is_ifvg and cfg.fib_gate and not g.fib_ok:\n                continue\n            if g.side == "BULL":\n                if cfg.direction == "PE":\n                    continue\n                if not g.touched and m.low <= g.top:\n                    g.touched = True\n                    self._bump("touch_bull")\n                if g.touched and m.close > g.top and m.close > m.open:\n                    g.used = True\n                    buf = cfg.sl_buf_atr * g.atr_at_birth\n                    self._bump("trig_ifvg" if is_ifvg else "trig_fvg")\n                    return Signal(trigger_min=mod, side="CE", kind=g.kind,\n                                  sl_level=g.bottom - buf, zone_top=g.top,\n                                  zone_bottom=g.bottom,\n                                  leg_target=None if is_ifvg else g.leg_high,\n                                  atr=g.atr_at_birth, gid=g.gid)\n            else:\n                if cfg.direction == "CE":\n                    continue\n                if not g.touched and m.high >= g.bottom:\n                    g.touched = True\n                    self._bump("touch_bear")\n                if g.touched and m.close < g.bottom and m.close < m.open:\n                    g.used = True\n                    buf = cfg.sl_buf_atr * g.atr_at_birth\n                    self._bump("trig_ifvg" if is_ifvg else "trig_fvg")\n                    return Signal(trigger_min=mod, side="PE", kind=g.kind,\n                                  sl_level=g.top + buf, zone_top=g.top,\n                                  zone_bottom=g.bottom,\n                                  leg_target=None if is_ifvg else g.leg_low,\n                                  atr=g.atr_at_birth, gid=g.gid)\n        return None\n\n\ndef session_signals(engine: FvgEngine, bars_1m: List[Bar], *,\n                    day_start_epoch: int, tf_minutes: int) -> List[Signal]:\n    """Walk one session causally: for each tf bar, run its 1m bars through\n    the trigger machine (gaps from EARLIER tf bars only), then close the\n    tf bar (detection). Returns every signal the day produced; the runner\n    decides which are tradeable (position, budget, window)."""\n    bars_tf = resample_session(bars_1m, day_start_epoch=day_start_epoch,\n                               tf_minutes=tf_minutes)\n    by_min = {(b.ts - day_start_epoch) // 60: b for b in bars_1m}\n    sigs: List[Signal] = []\n    engine.new_day()\n    for tb in bars_tf:\n        for mod in range(tb.start_min, tb.end_min + 1):\n            m = by_min.get(mod)\n            if m is None:\n                continue\n            s = engine.on_minute(m, mod)\n            if s is not None:\n                sigs.append(s)\n        engine.on_tf_close(tb)\n    return sigs\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  helpers shared with the runner\n# ─────────────────────────────────────────────────────────────────────────\ndef strike_step(strikes) -> float:\n    s = sorted({float(x) for x in strikes if x is not None})\n    gaps = [b - a for a, b in zip(s, s[1:]) if b - a > 0]\n    return min(gaps) if gaps else 50.0\n\n\ndef atm_strike(spot: float, step: float) -> float:\n    return round(spot / step) * step\n', 'backend/app/backtest/fvg/backtest_fvg_runner.py': '# backend/app/backtest/fvg/backtest_fvg_runner.py\n#\n# ── FVG_V1 ("Fissure") RUNNER ── Fair Value Gap / Inverse-FVG pullback\n# entries on NIFTY SPOT (5m), weekly option BUY at the next 1m open,\n# structural spot stop, timed exit. Sealed 2026-09-16 after five lab rounds\n# (docs/FVG_V1_BIBLE.md). Engine decisions D1–D7 in fvg_v1_engine.py.\n#\n# Fence: FVG_V1_20260916\n# LAB PARITY: this is tools/lab/fvg/fvg_fib_backtest.py\'s run() re-housed\n# under the app\'s runner contract (run_*_backtest signature, persist_run\n# trade surface, diag_* summary, dte_lot_mult). Same config keys, same\n# defaults where the lab had them; the test replays a synthetic corpus\n# through both when the lab is present and demands identical trades.\n#\n# ── RUNNER DECISIONS (R1–R6) ──────────────────────────────────────────────\n#   R1  Causality: the engine sees 1m bars of tf bar k only after tf bars\n#       < k closed; entry fills at the 1m OPEN of trigger_min + 1 (option\n#       AND spot). No unfinished-bar reads.\n#   R2  Contract: front weekly expiry = the smallest expiry >= day that has\n#       prints on that day (era-agnostic, holiday-shift-proof); a DTE above\n#       max_dte_sessions makes the day uncovered. ATM from entry_spot, shifted\n#       strike_offset steps OTM; nearest strike with a print at the fill\n#       minute (fallback counted). Same side as the signal.\n#   R3  Risk: stop = the engine\'s structural SPOT level. risk < sl_min_pts\n#       WIDENS the stop to sl_min_pts (counted); risk > sl_max_atr × ATR\n#       SKIPS the signal (counted). tp_mode off | rr (entry ± tp_rr × risk)\n#       | fib (impulse extreme when >= tp_fib_min_rr × risk away, else rr).\n#   R4  Exits per minute, pessimistic order (stop, target, breakeven update,\n#       time, EOD). sl_trigger "close" (SEALED): a 1m spot CLOSE through the\n#       level sells at the NEXT minute\'s option open (wick-immune, ORB_SLTRIG\n#       convention). "touch": intra-minute low/high; SL fills at the option\n#       LOW (sl_fill=low) or close, TP at close, both in one minute → SL.\n#       Time exit after hold_max minutes at close; EOD square-off at\n#       eod_square_off close. A missing option bar leaves the last mark\n#       (counted stale). Optional breakeven (be_rr, 0 = off).\n#   R5  Budgets: one position at a time (signals inside a position are\n#       skipped, counted); max_trades_per_day; entries inside\n#       [entry_from, entry_until); optional daily loss stop in R.\n#   R6  ATR is continuous across sessions and warms on `warmup_sessions`\n#       sessions before date_from (no trades there). Sessions = days with\n#       SPOT prints in the corpus (the lab\'s calendar; a special Saturday\n#       session in the corpus IS a session).\n#\n# ── CONTROL MODES (round 5 falsification, kept runnable) ──────────────────\n#   entry_mode fixed   → buy the side at fixed_entry_time EVERY session,\n#                        fixed_sl_pts stop, same exits (drift baseline)\n#   entry_mode matched → same, only on sessions with a tradeable signal\n#   Both LOST ₹1.8–10L over 2020–26 while the strategy made ₹5.5L — the\n#   edge is entry LOCATION, not day selection. Re-run them before trusting\n#   any change to the entry rule.\n#\n# ── FALSIFICATION TRIPWIRES (all in summary.diag_fvg) ─────────────────────\n#   * sl_fill_artifact_net: net(low fill) vs net(close fill) — sealed\n#     config uses close-trigger so this is ~0; watch it if touch is used.\n#   * time_pnl_share_pct: the timed exit CARRIES the net by design (the\n#     target was falsified); a change that moves net into TP/SL is a\n#     different strategy.\n#   * fvg vs ifvg, ce vs pe, entry_hour_hist, per-year signs, top5_share_pct.\n\nfrom __future__ import annotations\n\nimport uuid\nfrom dataclasses import dataclass, field\nfrom datetime import date, datetime, timedelta\nfrom typing import Callable, Dict, List, Optional, Tuple\n\ntry:\n    from app.backtest.fvg.fvg_v1_engine import (\n        Bar, ATR, EngineConfig, FvgEngine, Signal, session_signals,\n        strike_step, atm_strike, IST_OFFSET, SESSION_OPEN_MIN)\nexcept ImportError:                                        # standalone tests\n    from fvg_v1_engine import (  # type: ignore\n        Bar, ATR, EngineConfig, FvgEngine, Signal, session_signals,\n        strike_step, atm_strike, IST_OFFSET, SESSION_OPEN_MIN)\n\nINDEX_LOTS = {"NIFTY": 65, "BANKNIFTY": 35}\nSPLIT_YEAR = "2024"\n\n# ── SEALED 2026-09-16 (lab round 5, docs/FVG_V1_BIBLE.md) ──\nDEFAULTS: dict = {\n    # engine (D1–D7)\n    "tf": 5, "atr_len": 14, "disp_atr": 1.5, "gap_min_atr": 0.15,\n    "fib_gate": False, "fib_lo": 0.382, "fib_hi": 0.786, "fib_lookback": 10,\n    "sl_buf_atr": 0.10, "gap_max_age": 12, "trade_fvg": True, "trade_ifvg": True,\n    "direction": "CE", "max_gaps": 6,\n    # execution (R2–R6)\n    "strike_offset": 0, "premium_min": 0.0, "premium_max": 0.0,\n    "lots": 1, "lot_size": 0, "max_dte_sessions": 7,\n    "sl_min_pts": 15.0, "sl_max_atr": 3.0, "sl_fill": "low", "sl_trigger": "close",\n    "dte_min": 0, "dte_max": 99,\n    "tp_mode": "off", "tp_rr": 3.0, "tp_fib_min_rr": 1.0,\n    "be_rr": 0.0, "hold_max": 60,\n    "entry_from": "09:30", "entry_until": "11:00", "eod_square_off": "15:20",\n    "max_trades_per_day": 1, "daily_loss_r": 0.0,\n    "warmup_sessions": 5, "skip_expiry_day": True,\n    # control experiment\n    "entry_mode": "fvg", "fixed_entry_time": "10:00", "fixed_sl_pts": 30.0,\n}\n_BOOL_KEYS = ("fib_gate", "trade_fvg", "trade_ifvg", "skip_expiry_day")\n_INT_KEYS = ("tf", "atr_len", "fib_lookback", "gap_max_age", "max_gaps", "strike_offset",\n             "lots", "lot_size", "max_dte_sessions", "dte_min", "dte_max", "hold_max",\n             "max_trades_per_day", "warmup_sessions")\n_FLOAT_KEYS = ("disp_atr", "gap_min_atr", "fib_lo", "fib_hi", "sl_buf_atr", "premium_min",\n               "premium_max", "sl_min_pts", "sl_max_atr", "tp_rr", "tp_fib_min_rr", "be_rr",\n               "daily_loss_r", "fixed_sl_pts")\n\n\n@dataclass\nclass FVGTrade:\n    """persist_run-compatible attribute surface (object, no hedge_symbol)."""\n    tradingsymbol: str\n    symbol: str\n    instrument_type: str\n    strike: Optional[float]\n    expiry: Optional[str]\n    direction: str                     # always BUY\n    entry_ts: int\n    entry_price: float\n    sl: Optional[float]                # spot stop level\n    tp: Optional[float]                # spot target level (None when off)\n    exit_ts: Optional[int]\n    exit_price: Optional[float]\n    exit_reason: Optional[str]         # SL | BE | TP | TIME | EOD\n    qty: int\n    condition: str\n    ambiguous_fill: bool = False\n    pnl: float = 0.0\n    charges: float = 0.0\n    net_pnl: float = 0.0\n    max_adverse: Optional[float] = None\n    max_favorable: Optional[float] = None\n    gross: float = field(default=0.0)\n    net: float = field(default=0.0)\n    ambiguous: bool = field(default=False)\n    synthetic: bool = field(default=False)\n    synth_kind: Optional[str] = field(default=None)\n    entry_spot: Optional[float] = None\n    hold_min: int = 0\n    kind: str = "FVG"                  # FVG | IFVG | CTRL\n    risk_pts: float = 0.0\n    r_mult: float = 0.0\n    net_alt_fill: float = 0.0\n    dte: Optional[int] = None\n    stale_marks: int = 0\n\n\ndef _empty_summary() -> dict:\n    return {"total_trades": 0, "wins": 0, "losses": 0, "win_rate": 0.0,\n            "gross_pnl": 0.0, "total_charges": 0.0, "net_pnl": 0.0,\n            "max_drawdown": 0.0, "ambiguous_fills": 0}\n\n\ndef _hhmm(s: str, fallback: int) -> int:\n    try:\n        h, m = str(s).split(":")\n        v = int(h) * 60 + int(m)\n        return v if 0 <= v < 24 * 60 else fallback\n    except (ValueError, AttributeError):\n        return fallback\n\n\ndef _day_start_epoch(d: date) -> int:\n    return int((datetime(d.year, d.month, d.day)\n                - datetime(1970, 1, 1)).total_seconds()) - IST_OFFSET\n\n\ndef _epoch_day(ts: int) -> date:\n    return (datetime(1970, 1, 1) + timedelta(seconds=ts + IST_OFFSET)).date()\n\n\ndef _merge_cfg(override: Optional[dict]) -> dict:\n    cfg = dict(DEFAULTS)\n    for k, v in (override or {}).items():\n        if k in DEFAULTS or k == "dte_lot_mult":\n            cfg[k] = v\n    for k in _BOOL_KEYS:\n        v = cfg.get(k)\n        cfg[k] = (str(v).strip().lower() in ("1", "true", "yes", "on")) if isinstance(v, str) else bool(v)\n    for k in _INT_KEYS:\n        try:\n            cfg[k] = int(float(cfg[k]))\n        except (TypeError, ValueError):\n            cfg[k] = int(DEFAULTS[k])\n    for k in _FLOAT_KEYS:\n        try:\n            cfg[k] = float(cfg[k])\n        except (TypeError, ValueError):\n            cfg[k] = float(DEFAULTS[k])\n    cfg["lots"] = cfg["lots"] if cfg["lots"] > 0 else 1\n    _d = str(cfg.get("direction", "CE")).upper()\n    cfg["direction"] = _d if _d in ("BOTH", "CE", "PE") else "CE"\n    cfg["sl_fill"] = "close" if str(cfg.get("sl_fill", "low")).lower() == "close" else "low"\n    cfg["sl_trigger"] = "touch" if str(cfg.get("sl_trigger", "close")).lower() == "touch" else "close"\n    _tp = str(cfg.get("tp_mode", "off")).lower()\n    cfg["tp_mode"] = _tp if _tp in ("off", "rr", "fib") else "off"\n    _em = str(cfg.get("entry_mode", "fvg")).lower()\n    cfg["entry_mode"] = _em if _em in ("fvg", "fixed", "matched") else "fvg"\n    for k in ("entry_from", "entry_until", "eod_square_off", "fixed_entry_time"):\n        cfg[k] = str(cfg.get(k) or DEFAULTS[k])\n    try:\n        from app.backtest.engine.dte_lots import parse_dte_lot_mult   # ── DTE_LOT_MULT_20260911 ──\n        cfg["dte_lot_mult"] = parse_dte_lot_mult(cfg.get("dte_lot_mult"))\n    except ImportError:\n        cfg["dte_lot_mult"] = {}\n    return cfg\n\n\ndef _engine_cfg(cfg: dict) -> EngineConfig:\n    return EngineConfig(atr_len=cfg["atr_len"], disp_atr=cfg["disp_atr"],\n                        gap_min_atr=cfg["gap_min_atr"], fib_gate=cfg["fib_gate"],\n                        fib_lo=cfg["fib_lo"], fib_hi=cfg["fib_hi"],\n                        fib_lookback=cfg["fib_lookback"], sl_buf_atr=cfg["sl_buf_atr"],\n                        gap_max_age=cfg["gap_max_age"], trade_fvg=cfg["trade_fvg"],\n                        trade_ifvg=cfg["trade_ifvg"], direction=cfg["direction"],\n                        max_gaps=cfg["max_gaps"])\n\n\ndef run_fvg_backtest(\n    *, db_path: str, strategy_id: str, underlying: str,\n    date_from: date, date_to: date,\n    config_override: Optional[dict] = None,\n    progress_cb: Optional[Callable[[dict], None]] = None,\n    cancel_cb: Optional[Callable[[], bool]] = None,\n) -> Dict:\n    try:\n        from app.event_bus.audit_logger import audit_muted\n        with audit_muted():\n            return _impl(db_path=db_path, strategy_id=strategy_id,\n                         underlying=underlying, date_from=date_from,\n                         date_to=date_to, config_override=config_override,\n                         progress_cb=progress_cb, cancel_cb=cancel_cb)\n    except ImportError:\n        return _impl(db_path=db_path, strategy_id=strategy_id,\n                     underlying=underlying, date_from=date_from,\n                     date_to=date_to, config_override=config_override,\n                     progress_cb=progress_cb, cancel_cb=cancel_cb)\n\n\ndef _abort(cfg, strategy_id, reason) -> Dict:\n    return {"run_id": None, "aborted": True, "reason": reason,\n            "trades": [], "summary": _empty_summary(),\n            "config": cfg, "strategy_id": strategy_id}\n\n\nclass _Corpus:\n    """Read-only corpus access on the shared CandleSource connection (same\n    queries as the lab runner; symbol-day option bars cached)."""\n\n    def __init__(self, conn, underlying: str):\n        self.c = conn\n        self.u = underlying\n        self.spot: Dict[date, List[Bar]] = {}\n        self.expiry_ranges: List[Tuple[str, int, int]] = []\n        self._opt: Dict[Tuple[str, int], Dict[int, Bar]] = {}\n        self._order: List[Tuple[str, int]] = []\n\n    def load_spot(self, d_from: date, d_to: date) -> None:\n        ts_from, ts_to = _day_start_epoch(d_from), _day_start_epoch(d_to) + 86400\n        rows = self.c.execute(\n            """SELECT ts, open, high, low, close FROM backtest_candles_1m\n               WHERE underlying=? AND instrument_type=\'SPOT\' AND ts>=? AND ts<?\n               ORDER BY ts""", (self.u, ts_from, ts_to)).fetchall()\n        for r in rows:\n            self.spot.setdefault(_epoch_day(int(r["ts"])), []).append(\n                Bar(int(r["ts"]), float(r["open"]), float(r["high"]), float(r["low"]), float(r["close"])))\n\n    def load_expiry_ranges(self) -> None:\n        rows = self.c.execute(\n            """SELECT expiry, MIN(ts) AS a, MAX(ts) AS b FROM backtest_candles_1m\n               WHERE underlying=? AND expiry IS NOT NULL AND expiry<>\'\'\n                 AND instrument_type IN (\'CE\',\'PE\')\n               GROUP BY expiry ORDER BY expiry""", (self.u,)).fetchall()\n        self.expiry_ranges = [(str(r["expiry"]), int(r["a"]), int(r["b"])) for r in rows]\n\n    def front_expiry(self, d: date) -> Optional[str]:\n        ds, de = _day_start_epoch(d), _day_start_epoch(d) + 86400\n        iso = d.isoformat()\n        for exp, a, b in self.expiry_ranges:\n            if exp >= iso and a < de and b >= ds:\n                return exp\n        return None\n\n    def chain_at(self, expiry: str, ts: int, side: str) -> List[dict]:\n        rows = self.c.execute(\n            """SELECT tradingsymbol, strike FROM backtest_candles_1m\n               WHERE underlying=? AND expiry=? AND ts=? AND instrument_type=? AND open>0""",\n            (self.u, expiry, ts, side)).fetchall()\n        return [{"tradingsymbol": r["tradingsymbol"], "strike": float(r["strike"])} for r in rows]\n\n    def option_day(self, sym: str, ds: int) -> Dict[int, Bar]:\n        key = (sym, ds)\n        hit = self._opt.get(key)\n        if hit is not None:\n            return hit\n        rows = self.c.execute(\n            """SELECT ts, open, high, low, close FROM backtest_candles_1m\n               WHERE tradingsymbol=? AND ts>=? AND ts<? ORDER BY ts""",\n            (sym, ds, ds + 86400)).fetchall()\n        out = {int(r["ts"]): Bar(int(r["ts"]), float(r["open"]), float(r["high"]),\n                                 float(r["low"]), float(r["close"])) for r in rows}\n        self._opt[key] = out\n        self._order.append(key)\n        if len(self._order) > 4000:\n            self._opt.pop(self._order.pop(0), None)\n        return out\n\n\ndef _impl(*, db_path, strategy_id, underlying, date_from, date_to,\n          config_override, progress_cb, cancel_cb) -> Dict:\n    from app.backtest.data.candle_source import CandleSource\n    from app.backtest.charges.charges_model import charges_for_long_trade\n    from app.backtest.util.lot_sizes import resolve_lot\n    from app.event_bus.audit_logger import write_audit_log\n\n    cfg = _merge_cfg(config_override)\n    underlying = str(underlying or "NIFTY").upper()\n    index_lot = INDEX_LOTS.get(underlying)\n    if index_lot is None:\n        return _abort(cfg, strategy_id, f"FVG_V1 is index-only; no lot constant for {underlying}.")\n    lot_size, lot_source = resolve_lot(\n        underlying=underlying, is_stock=False, cfg_lot=cfg["lot_size"],\n        index_lot=index_lot, db_path=db_path)\n    if lot_size is None:\n        return _abort(cfg, strategy_id, f"no lot size for {underlying}")\n    qty = cfg["lots"] * lot_size\n\n    tf = cfg["tf"]\n    e_from = _hhmm(cfg["entry_from"], 9 * 60 + 30)\n    e_until = _hhmm(cfg["entry_until"], 11 * 60)\n    eod_min = _hhmm(cfg["eod_square_off"], 15 * 60 + 20)\n    if not (SESSION_OPEN_MIN <= e_from < e_until <= eod_min <= 15 * 60 + 29):\n        return _abort(cfg, strategy_id,\n                      f"time order must be 09:15 <= entry_from {cfg[\'entry_from\']} < "\n                      f"entry_until {cfg[\'entry_until\']} <= eod {cfg[\'eod_square_off\']} <= 15:29")\n    if not (1 <= tf <= 30):\n        return _abort(cfg, strategy_id, "tf must be 1..30")\n    if not (2 <= cfg["atr_len"] <= 200):\n        return _abort(cfg, strategy_id, "atr_len must be 2..200")\n    if cfg["disp_atr"] < 0 or cfg["gap_min_atr"] < 0:\n        return _abort(cfg, strategy_id, "disp_atr / gap_min_atr must be >= 0")\n    if cfg["tp_mode"] != "off" and cfg["tp_rr"] <= 0:\n        return _abort(cfg, strategy_id, "tp_rr must be > 0 when tp_mode is on")\n    if not (1 <= cfg["hold_max"] <= 375):\n        return _abort(cfg, strategy_id, "hold_max must be 1..375")\n    if cfg["sl_min_pts"] < 0 or cfg["sl_max_atr"] < 0:\n        return _abort(cfg, strategy_id, "sl_min_pts / sl_max_atr must be >= 0")\n    if cfg["dte_min"] > cfg["dte_max"]:\n        return _abort(cfg, strategy_id, "dte_min must be <= dte_max")\n    if cfg["premium_max"] > 0 and cfg["premium_min"] >= cfg["premium_max"]:\n        return _abort(cfg, strategy_id, "premium band needs min < max")\n    if abs(cfg["strike_offset"]) > 10:\n        return _abort(cfg, strategy_id, "strike_offset must be within ±10 steps")\n    if cfg["entry_mode"] != "fvg" and cfg["fixed_sl_pts"] <= 0:\n        return _abort(cfg, strategy_id, "fixed_sl_pts must be > 0 in a control mode")\n\n    src = CandleSource(db_path)\n    corpus = _Corpus(src._conn(), underlying)\n    corpus.load_spot(date_from - timedelta(days=30), date_to)\n    corpus.load_expiry_ranges()\n    sessions = sorted(corpus.spot)\n    if not sessions:\n        src.close()\n        return _abort(cfg, strategy_id, f"no {underlying} SPOT rows in the corpus for that window")\n    session_index = {d: i for i, d in enumerate(sessions)}\n    idx_from = next((i for i, d in enumerate(sessions) if d >= date_from), len(sessions))\n    warm = sessions[max(0, idx_from - cfg["warmup_sessions"]):idx_from]\n    days = [d for d in sessions[idx_from:] if d <= date_to]\n\n    atr = ATR(cfg["atr_len"])\n    eng = FvgEngine(_engine_cfg(cfg), atr)\n    warmup_bars = 0\n    for wd in warm:\n        session_signals(eng, corpus.spot[wd], day_start_epoch=_day_start_epoch(wd), tf_minutes=tf)\n        warmup_bars += len(eng.bars)\n\n    from app.backtest.engine.dte_lots import lots_for_day as _lots_for_day   # ── DTE_LOT_MULT_20260911 ──\n\n    diag: Dict[str, object] = {k: 0 for k in (\n        "days_total", "days_traded", "days_uncovered", "days_thin", "days_skipped_expiry",\n        "days_skipped_dte", "dte_skipped_days", "dte_scaled_days",\n        "signals_total", "sig_dropped_open", "sig_dropped_budget", "sig_dropped_window",\n        "sig_dropped_daily_loss", "sig_no_spot_bar", "sig_bad_risk", "sig_risk_too_wide",\n        "sig_sl_widened", "sig_no_candidate", "sig_no_fill", "sig_band_reject",\n        "strike_fallbacks", "tp_fib_fallback", "entries", "ce_entries", "pe_entries",\n        "fvg_entries", "ifvg_entries", "ctrl_entries", "sl_exits", "be_exits", "tp_exits",\n        "time_exits", "eod_exits", "sl_in_entry_minute", "stale_marks", "be_armed", "hold_sum")}\n    diag.update({"warmup_sessions": len(warm), "warmup_bars": warmup_bars,\n                 "entry_mode": cfg["entry_mode"], "sl_trigger": cfg["sl_trigger"],\n                 "entry_hour_hist": {}, "underlying": underlying, "lot_size": lot_size,\n                 "lot_source": lot_source, "qty": qty,\n                 "dte_lot_mult": {str(k): v for k, v in cfg["dte_lot_mult"].items()},\n                 "corpus_db": str(db_path).rsplit("/", 1)[-1]})\n    for k in ("sl", "be", "tp", "time", "eod"):\n        diag[f"{k}_pnl_gross"] = 0.0\n    diag["ce_net"] = diag["pe_net"] = diag["fvg_net"] = diag["ifvg_net"] = 0.0\n\n    trades: List[FVGTrade] = []\n\n    for i, d in enumerate(days):\n        if cancel_cb and cancel_cb():\n            break\n        if progress_cb:\n            progress_cb({"day": i + 1, "total_days": len(days),\n                         "date": d.isoformat(), "trades": len(trades)})\n        diag["days_total"] += 1\n        bars_1m = corpus.spot[d]\n        ds = _day_start_epoch(d)\n        if len(bars_1m) < 300:\n            diag["days_thin"] += 1\n        # the indicator ALWAYS advances (R6), even on days we do not trade\n        sigs = session_signals(eng, bars_1m, day_start_epoch=ds, tf_minutes=tf)\n        if not sigs and cfg["entry_mode"] != "fixed":\n            continue\n        exp = corpus.front_expiry(d)\n        if exp is None:\n            diag["days_uncovered"] += 1\n            continue\n        exp_d = date.fromisoformat(exp)\n        if exp_d in session_index:\n            dte = max(0, session_index[exp_d] - session_index[d])\n        else:                               # expiry beyond the loaded window: weekday count\n            dte = sum(1 for k in range(1, (exp_d - d).days + 1)\n                      if (d + timedelta(days=k)).weekday() < 5)\n        if dte > cfg["max_dte_sessions"]:\n            diag["days_uncovered"] += 1\n            continue\n        if cfg["skip_expiry_day"] and dte == 0:\n            diag["days_skipped_expiry"] += 1\n            continue\n        if not (cfg["dte_min"] <= dte <= cfg["dte_max"]):\n            diag["days_skipped_dte"] += 1\n            continue\n        day_qty = qty\n        if cfg["dte_lot_mult"]:                             # ── DTE_LOT_MULT_20260911 ──\n            _lots, _tag = _lots_for_day(cfg["lots"], cfg["dte_lot_mult"], dte)\n            if _tag == "skip":\n                diag["dte_skipped_days"] += 1\n                continue\n            if _tag == "scaled":\n                diag["dte_scaled_days"] += 1\n            day_qty = _lots * lot_size\n        by_min = {(b.ts - ds) // 60: b for b in bars_1m}\n        if cfg["entry_mode"] != "fvg":\n            side = "PE" if cfg["direction"] == "PE" else "CE"\n            if cfg["entry_mode"] == "matched" and not any(\n                    x.side == side and e_from <= x.trigger_min + 1 < e_until for x in sigs):\n                continue\n            fmin = _hhmm(cfg["fixed_entry_time"], 10 * 60)\n            sb0 = by_min.get(fmin)\n            if sb0 is None:\n                diag["sig_no_spot_bar"] += 1\n                continue\n            lvl = (float(sb0.open) - cfg["fixed_sl_pts"] if side == "CE"\n                   else float(sb0.open) + cfg["fixed_sl_pts"])\n            sigs = [Signal(trigger_min=fmin - 1, side=side, kind="CTRL", sl_level=lvl,\n                           zone_top=0.0, zone_bottom=0.0, leg_target=None,\n                           atr=float(eng.atr.value or cfg["fixed_sl_pts"]), gid=0)]\n        diag["signals_total"] += len(sigs)\n        open_until = -1\n        day_trades = 0\n        day_r_sum = 0.0\n        traded = False\n        step_cache: Optional[float] = None\n\n        for s in sigs:\n            entry_min = s.trigger_min + 1\n            if entry_min <= open_until:\n                diag["sig_dropped_open"] += 1\n                continue\n            if cfg["max_trades_per_day"] and day_trades >= cfg["max_trades_per_day"]:\n                diag["sig_dropped_budget"] += 1\n                continue\n            if not (e_from <= entry_min < e_until):\n                diag["sig_dropped_window"] += 1\n                continue\n            if cfg["daily_loss_r"] > 0 and day_r_sum <= -cfg["daily_loss_r"]:\n                diag["sig_dropped_daily_loss"] += 1\n                continue\n            sb = by_min.get(entry_min)\n            if sb is None:\n                diag["sig_no_spot_bar"] += 1\n                continue\n            entry_spot = float(sb.open)\n            bull = s.side == "CE"\n            sl = s.sl_level\n            risk = (entry_spot - sl) if bull else (sl - entry_spot)\n            if risk <= 0:\n                diag["sig_bad_risk"] += 1\n                continue\n            if risk < cfg["sl_min_pts"]:\n                risk = cfg["sl_min_pts"]\n                sl = entry_spot - risk if bull else entry_spot + risk\n                diag["sig_sl_widened"] += 1\n            if cfg["sl_max_atr"] > 0 and risk > cfg["sl_max_atr"] * s.atr:\n                diag["sig_risk_too_wide"] += 1\n                continue\n            tp: Optional[float] = None\n            if cfg["tp_mode"] != "off":\n                tp = entry_spot + cfg["tp_rr"] * risk if bull else entry_spot - cfg["tp_rr"] * risk\n                if cfg["tp_mode"] == "fib":\n                    lt = s.leg_target\n                    ok = lt is not None and (\n                        (lt - entry_spot) if bull else (entry_spot - lt)) >= cfg["tp_fib_min_rr"] * risk\n                    if ok:\n                        tp = float(lt)\n                    else:\n                        diag["tp_fib_fallback"] += 1\n            fill_ts = ds + entry_min * 60\n            chain = corpus.chain_at(exp, fill_ts, s.side)\n            if not chain:\n                diag["sig_no_candidate"] += 1\n                continue\n            if step_cache is None:\n                step_cache = strike_step([c["strike"] for c in chain])\n            sign = 1 if bull else -1\n            target_strike = atm_strike(entry_spot, step_cache) + sign * cfg["strike_offset"] * step_cache\n            mc = min(chain, key=lambda c: (abs(c["strike"] - target_strike), c["strike"]))\n            fallback = int(mc["strike"] != target_strike)\n            diag["strike_fallbacks"] += fallback\n            ob = corpus.option_day(mc["tradingsymbol"], ds)\n            fb = ob.get(fill_ts)\n            if fb is None or not fb.open:\n                diag["sig_no_fill"] += 1\n                continue\n            entry_px = float(fb.open)\n            if (cfg["premium_max"] > 0 and entry_px >= cfg["premium_max"]) or \\\n               (cfg["premium_min"] > 0 and entry_px < cfg["premium_min"]):\n                diag["sig_band_reject"] += 1\n                continue\n\n            hh, mm = entry_min // 60, entry_min % 60\n            tp_tag = ("TPoff" if tp is None else\n                      f"TP{\'fib\' if cfg[\'tp_mode\'] == \'fib\' else \'\'}{cfg[\'tp_rr\']:g}R")\n            t = FVGTrade(\n                tradingsymbol=mc["tradingsymbol"], symbol=mc["tradingsymbol"],\n                instrument_type=s.side, strike=float(mc["strike"]), expiry=exp,\n                direction="BUY", entry_ts=fill_ts, entry_price=round(entry_px, 2),\n                sl=round(sl, 2), tp=(round(tp, 2) if tp is not None else None),\n                exit_ts=None, exit_price=None, exit_reason=None, qty=day_qty,\n                condition=(f"{s.kind}·{s.side}·{hh:02d}:{mm:02d}·{tf}m·disp{cfg[\'disp_atr\']:g}"\n                           f"·SLstruct{\'@close\' if cfg[\'sl_trigger\'] == \'close\' else \'\'}"\n                           f"·{tp_tag}·hold{cfg[\'hold_max\']}m{\'·FB\' if fallback else \'\'}"),\n                entry_spot=round(entry_spot, 2), kind=s.kind, risk_pts=round(risk, 2), dte=dte)\n            diag["entries"] += 1\n            diag["ce_entries" if bull else "pe_entries"] += 1\n            diag[{"FVG": "fvg_entries", "IFVG": "ifvg_entries"}.get(s.kind, "ctrl_entries")] += 1\n            hk = f"{hh:02d}"\n            diag["entry_hour_hist"][hk] = diag["entry_hour_hist"].get(hk, 0) + 1\n            day_trades += 1\n            traded = True\n\n            last_mark = entry_px\n            mae = mfe = 0.0\n            cur_sl, be_armed = sl, False\n            exit_min = eod_min\n            exit_px = alt_px = None\n            reason = None\n            for m in range(entry_min, eod_min + 1):\n                o = ob.get(ds + m * 60)\n                if o is not None:\n                    last_mark = float(o.close)\n                    mae = min(mae, float(o.low) - entry_px)\n                    mfe = max(mfe, float(o.high) - entry_px)\n                else:\n                    t.stale_marks += 1\n                if m >= eod_min:\n                    exit_px = alt_px = last_mark\n                    reason, exit_min = "EOD", m\n                    break\n                b = by_min.get(m)\n                if b is not None:\n                    if cfg["sl_trigger"] == "close":      # wick-immune (ORB_SLTRIG convention)\n                        sl_hit = (b.close <= cur_sl) if bull else (b.close >= cur_sl)\n                        tp_hit = tp is not None and ((b.close >= tp) if bull else (b.close <= tp))\n                    else:\n                        sl_hit = (b.low <= cur_sl) if bull else (b.high >= cur_sl)\n                        tp_hit = tp is not None and ((b.high >= tp) if bull else (b.low <= tp))\n                    if sl_hit or tp_hit:\n                        reason = ("BE" if be_armed else "SL") if sl_hit else "TP"\n                        if cfg["sl_trigger"] == "close":\n                            m2 = min(m + 1, eod_min)\n                            o2 = ob.get(ds + m2 * 60)\n                            exit_px = float(o2.open) if (o2 is not None and o2.open) else last_mark\n                            alt_px = last_mark\n                            exit_min = m2\n                        elif sl_hit:\n                            if o is None:\n                                exit_px = alt_px = last_mark\n                            else:\n                                exit_px = float(o.close) if cfg["sl_fill"] == "close" else float(o.low)\n                                alt_px = float(o.close) if cfg["sl_fill"] == "low" else float(o.low)\n                            exit_min = m\n                        else:\n                            exit_px = alt_px = last_mark\n                            exit_min = m\n                        if sl_hit and m == entry_min:\n                            diag["sl_in_entry_minute"] += 1\n                        break\n                    if cfg["be_rr"] > 0 and not be_armed:\n                        fav = (b.high - entry_spot) if bull else (entry_spot - b.low)\n                        if fav >= cfg["be_rr"] * risk:\n                            be_armed, cur_sl = True, entry_spot\n                            diag["be_armed"] += 1\n                if m - entry_min + 1 >= cfg["hold_max"]:\n                    exit_px = alt_px = last_mark\n                    reason, exit_min = "TIME", m\n                    break\n            if exit_px is None:\n                exit_px = alt_px = last_mark\n                reason, exit_min = "EOD", eod_min\n            gross = (exit_px - entry_px) * day_qty\n            ch = charges_for_long_trade(entry_price=entry_px, exit_price=exit_px,\n                                        qty=day_qty).total_charges\n            net = gross - ch\n            t.exit_ts = ds + exit_min * 60\n            t.exit_price, t.exit_reason = round(exit_px, 2), reason\n            t.hold_min = exit_min - entry_min + 1\n            t.pnl = t.gross = round(gross, 2)\n            t.charges = round(ch, 2)\n            t.net_pnl = t.net = round(net, 2)\n            alt_ch = charges_for_long_trade(entry_price=entry_px, exit_price=alt_px,\n                                            qty=day_qty).total_charges\n            t.net_alt_fill = round((alt_px - entry_px) * day_qty - alt_ch, 2)\n            t.max_adverse, t.max_favorable = round(mae * day_qty, 2), round(mfe * day_qty, 2)\n            xs = by_min.get(exit_min)\n            if xs is not None and risk > 0:\n                sp = float(xs.close)\n                t.r_mult = round(((sp - entry_spot) if bull else (entry_spot - sp)) / risk, 2)\n            key = reason.lower()\n            diag[f"{key}_exits"] += 1\n            diag[f"{key}_pnl_gross"] += round(net, 2)\n            diag["hold_sum"] += t.hold_min\n            diag["stale_marks"] += t.stale_marks\n            diag["ce_net" if bull else "pe_net"] += round(net, 2)\n            if s.kind in ("FVG", "IFVG"):\n                diag[f"{s.kind.lower()}_net"] += round(net, 2)\n            trades.append(t)\n            day_r_sum += t.r_mult\n            open_until = exit_min\n        if traded:\n            diag["days_traded"] += 1\n\n    src.close()\n    for k, v in eng.diag.items():\n        diag[f"eng_{k}"] = v\n    if diag["entries"]:\n        diag["avg_hold_min"] = round(diag["hold_sum"] / diag["entries"], 1)\n        diag["avg_risk_pts"] = round(sum(t.risk_pts for t in trades) / len(trades), 2)\n        diag["avg_premium"] = round(sum(t.entry_price for t in trades) / len(trades), 2)\n    summary = _summarize(trades, diag)\n    write_audit_log(\n        f"[BACKTEST][{strategy_id}] {underlying} {date_from}..{date_to}: "\n        f"{summary[\'total_trades\']} trades, net {summary[\'net_pnl\']:,.0f}, "\n        f"DD {summary[\'max_drawdown\']:,.0f}, exits SL {diag[\'sl_exits\']} / BE "\n        f"{diag[\'be_exits\']} / TP {diag[\'tp_exits\']} / TIME {diag[\'time_exits\']} / "\n        f"EOD {diag[\'eod_exits\']}, years +{diag.get(\'pos_years\', 0)}/{diag.get(\'n_years\', 0)}, "\n        f"worst month {diag.get(\'worst_month\', 0):,.0f}"\n    )\n    return {"run_id": str(uuid.uuid4()), "summary": summary,\n            "config": cfg, "trades": trades, "strategy_id": strategy_id}\n\n\ndef _summarize(trades: List[FVGTrade], diag: dict) -> dict:\n    closed = [t for t in trades if t.exit_price is not None]\n    if not closed:\n        s = _empty_summary()\n        s["diag_fvg"] = diag\n        return s\n    years: Dict[str, float] = {}\n    months: Dict[str, float] = {}\n    eq = peak = mdd = 0.0\n    for t in sorted(closed, key=lambda x: (x.exit_ts or 0, x.entry_ts or 0)):\n        dd = _epoch_day(t.entry_ts).isoformat()\n        years[dd[:4]] = years.get(dd[:4], 0.0) + t.net_pnl\n        months[dd[:7]] = months.get(dd[:7], 0.0) + t.net_pnl\n        eq += t.net_pnl\n        peak = max(peak, eq)\n        mdd = max(mdd, peak - eq)\n    consec = worst_consec = 0\n    for ym in sorted(months):\n        consec = consec + 1 if months[ym] < 0 else 0\n        worst_consec = max(worst_consec, consec)\n    nets = [t.net_pnl for t in closed]\n    wins = sum(1 for n in nets if n > 0)\n    net = sum(nets)\n    top5 = sum(x for x in sorted(nets, reverse=True)[:5] if x > 0)\n    # ── scoreboard in Anbu\'s priority order ──\n    diag["years"] = {y: round(v, 2) for y, v in sorted(years.items())}\n    diag["pos_years"], diag["n_years"] = sum(1 for v in years.values() if v > 0), len(years)\n    diag["worst_month"] = round(min(months.values()), 2)\n    diag["worst_month_ym"] = min(months, key=months.get)\n    diag["max_consec_losing_months"] = worst_consec\n    diag["pos_months"], diag["n_months"] = sum(1 for v in months.values() if v > 0), len(months)\n    diag["net_pre_split"] = round(sum(v for y, v in years.items() if y < SPLIT_YEAR), 2)\n    diag["net_post_split"] = round(sum(v for y, v in years.items() if y >= SPLIT_YEAR), 2)\n    diag["net_alt_fill"] = round(sum(t.net_alt_fill for t in closed), 2)\n    diag["sl_fill_artifact_net"] = round(diag["net_alt_fill"] - net, 2)\n    diag["top5_share_pct"] = round(100.0 * top5 / net, 1) if abs(net) > 1e-9 else 0.0\n    diag["net_without_top5"] = round(net - top5, 2)\n    if abs(net) > 1e-9:\n        for k in ("sl", "be", "tp", "time", "eod"):\n            diag[f"{k}_pnl_share_pct"] = round(100.0 * diag[f"{k}_pnl_gross"] / net, 1)\n    for k in ("sl", "be", "tp", "time", "eod", "ce", "pe", "fvg", "ifvg"):\n        kk = f"{k}_pnl_gross" if k in ("sl", "be", "tp", "time", "eod") else f"{k}_net"\n        diag[kk] = round(diag[kk], 2)\n    return {\n        "total_trades": len(closed), "wins": wins,\n        "losses": sum(1 for n in nets if n < 0),\n        "win_rate": round(100.0 * wins / len(closed), 2),\n        "gross_pnl": round(sum(t.pnl for t in closed), 2),\n        "total_charges": round(sum(t.charges for t in closed), 2),\n        "net_pnl": round(net, 2), "max_drawdown": round(mdd, 2),\n        "ambiguous_fills": 0,\n        "diag_fvg": diag,\n    }\n', 'backend/app/backtest/fvg/test_fvg_runner_sim.py': '# backend/app/backtest/fvg/test_fvg_runner_sim.py\n#\n# ── FVG_V1_20260916 ── behavioural simulation suite. Standalone:\n#   cd backend && PYTHONPATH=$PWD python3 app/backtest/fvg/test_fvg_runner_sim.py\n# Part 1 exercises the pure engine on hand-built bars; part 2 runs the\n# whole runner against a synthetic corpus (real backtest_candles_1m shape:\n# SPOT rows + BS-priced weekly chain) and checks fill/exit/overlap/budget\n# invariants, the control modes and dte_lot_mult; part 3 is LAB PARITY —\n# when tools/lab/fvg/fvg_fib_backtest.py exists in the repo, the same\n# synthetic corpus is replayed through the lab runner and every trade must\n# match to the paisa. Nothing here touches ~/.scalp-app.\n\nfrom __future__ import annotations\n\nimport math\nimport os\nimport random\nimport sqlite3\nimport sys\nimport tempfile\nfrom datetime import date, datetime, timedelta\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nBACKEND = os.path.abspath(os.path.join(HERE, "..", "..", ".."))\nREPO = os.path.abspath(os.path.join(BACKEND, ".."))\nsys.path.insert(0, HERE)\nsys.path.insert(0, BACKEND)\nos.environ.setdefault("SCALP_LOT_SIZE_OFFLINE", "1")\n\nfrom fvg_v1_engine import (Bar, ATR, EngineConfig, FvgEngine, resample_session,   # noqa: E402\n                           session_signals, SESSION_OPEN_MIN, IST_OFFSET)\nfrom backtest_fvg_runner import run_fvg_backtest, _merge_cfg, _hhmm, DEFAULTS   # noqa: E402\n\nFAILS = []\n\n\ndef check(name: str, ok: bool, note: str = "") -> None:\n    print(f"  {\'PASS\' if ok else \'FAIL\'}  {name}{(\'  — \' + note) if (note and not ok) else \'\'}")\n    if not ok:\n        FAILS.append(name)\n\n\ndef ds_of(d: date) -> int:\n    return int((datetime(d.year, d.month, d.day) - datetime(1970, 1, 1)).total_seconds()) - IST_OFFSET\n\n\ndef m1(ds: int, mod: int, o, h, l, c) -> Bar:\n    return Bar(ds + mod * 60, o, h, l, c)\n\n\ndef build_day(ds: int, tf: int, tf_bars: list) -> list:\n    """Expand (o,h,l,c) tf bars from 09:15 into 1m bars reproducing that OHLC."""\n    out = []\n    for k, (o, h, l, c) in enumerate(tf_bars):\n        base = SESSION_OPEN_MIN + k * tf\n        mins = []\n        for i in range(tf):\n            if i == 0:\n                mins.append((o, o, o, o))\n            elif i == 1:\n                mins.append((o, h, o, h))\n            elif i == 2:\n                mins.append((h, h, l, l))\n            elif i == tf - 1:\n                mins.append((l, max(l, c), min(l, c), c))\n            else:\n                mins.append((l, l, l, l))\n        if tf < 4:\n            mins = [(o, h, l, c)] + [(c, c, c, c)] * (tf - 1)\n        for i, (a, b, c_, d) in enumerate(mins):\n            out.append(m1(ds, base + i, a, b, c_, d))\n    return out\n\n\n# ═════════════════════════════════════ 1. engine ═════════════════════════\nprint("── engine ──")\nD0 = date(2026, 3, 4)\nDS = ds_of(D0)\nTF = 5\nwarm = [(24000 + (i % 3), 24006 + (i % 3), 23996 + (i % 3), 24002 + (i % 3)) for i in range(16)]\nc0, c1, c2 = (24002, 24010, 23998, 24005), (24005, 24062, 24004, 24060), (24060, 24075, 24040, 24070)\nbars_tf = warm + [c0, c1, c2]\nbars = build_day(DS, TF, bars_tf)\neng = FvgEngine(EngineConfig(), ATR(14))\nsigs = session_signals(eng, bars, day_start_epoch=DS, tf_minutes=TF)\ncheck("bull FVG born", eng.diag.get("gap_born_bull", 0) == 1, str(eng.diag))\ng = eng.gaps[0] if eng.gaps else None\ncheck("zone = [c0.high, c2.low]", g is not None and g.bottom == 24010 and g.top == 24040)\ncheck("no signal on the birth bar", sigs == [])\nnb = SESSION_OPEN_MIN + 19 * TF\ntail = [m1(DS, nb, 24068, 24070, 24035, 24038), m1(DS, nb + 1, 24038, 24045, 24030, 24039),\n        m1(DS, nb + 2, 24044, 24052, 24042, 24050), m1(DS, nb + 3, 24050, 24055, 24048, 24052)]\neng2 = FvgEngine(EngineConfig(), ATR(14))\nsigs = session_signals(eng2, bars + tail, day_start_epoch=DS, tf_minutes=TF)\ncheck("CE FVG signal on touch + rejection close", len(sigs) == 1 and sigs[0].side == "CE"\n      and sigs[0].kind == "FVG" and sigs[0].trigger_min == nb + 2, str(sigs))\ncheck("structural stop below the band", bool(sigs) and 24000 < sigs[0].sl_level < 24010)\ncheck("gap consumed once", bool(eng2.gaps) and eng2.gaps[0].used)\neng3 = FvgEngine(EngineConfig(direction="PE"), ATR(14))\ncheck("direction=PE suppresses CE", session_signals(eng3, bars + tail, day_start_epoch=DS, tf_minutes=TF) == [])\nwarm_b = list(warm)\nwarm_b[10] = (23900, 23905, 23800, 23900)\neng4 = FvgEngine(EngineConfig(), ATR(14))\nsession_signals(eng4, build_day(DS, TF, warm_b + [c0, c1, c2]), day_start_epoch=DS, tf_minutes=TF)\ncheck("fib gate rejects a gap in the top 38% of the leg", bool(eng4.gaps) and not eng4.gaps[0].fib_ok)\ninv = [(24068, 24070, 23990, 23995)]\nbars_inv = build_day(DS, TF, bars_tf + inv)\nnb2 = SESSION_OPEN_MIN + 20 * TF\ntail2 = [m1(DS, nb2, 23995, 24015, 23994, 24012), m1(DS, nb2 + 1, 24012, 24020, 24000, 24005),\n         m1(DS, nb2 + 2, 24005, 24008, 23990, 23992)]\neng5 = FvgEngine(EngineConfig(), ATR(14))\nsigs = session_signals(eng5, bars_inv + tail2, day_start_epoch=DS, tf_minutes=TF)\ncheck("inversion → IFVG PE signal", eng5.diag.get("gap_inverted", 0) == 1 and len(sigs) == 1\n      and sigs[0].side == "PE" and sigs[0].kind == "IFVG" and sigs[0].leg_target is None, str(sigs))\neng6 = FvgEngine(EngineConfig(trade_ifvg=False), ATR(14))\ncheck("trade_ifvg=off suppresses it", session_signals(eng6, bars_inv + tail2, day_start_epoch=DS, tf_minutes=TF) == [])\nquiet = [(24060, 24064, 24056, 24060)] * 13\nlate = [m1(DS, SESSION_OPEN_MIN + 32 * TF, 24060, 24061, 24035, 24038),\n        m1(DS, SESSION_OPEN_MIN + 32 * TF + 1, 24038, 24050, 24037, 24049)]\neng7 = FvgEngine(EngineConfig(gap_max_age=12), ATR(14))\ncheck("gap expires after gap_max_age", eng7.diag.get("gap_expired", 0) == 0 and\n      session_signals(eng7, build_day(DS, TF, bars_tf + quiet) + late, day_start_epoch=DS, tf_minutes=TF) == []\n      and eng7.diag.get("gap_expired", 0) == 1)\nrs = resample_session(bars, day_start_epoch=DS, tf_minutes=TF)\ncheck("resample reproduces tf OHLC", len(rs) == len(bars_tf) and rs[17].high == 24062 and rs[18].low == 24040)\n\n# ═══════════════════════════ 2. runner on a synthetic corpus ══════════════\nprint("── runner ──")\n\n\ndef _ncdf(x: float) -> float:\n    return 0.5 * (1.0 + math.erf(x / math.sqrt(2)))\n\n\ndef bs(spot: float, k: float, t: float, iv: float, kind: str) -> float:\n    if t <= 0:\n        return max(spot - k, 0.0) if kind == "CE" else max(k - spot, 0.0)\n    d1 = (math.log(spot / k) + 0.5 * iv * iv * t) / (iv * math.sqrt(t))\n    d2 = d1 - iv * math.sqrt(t)\n    return (spot * _ncdf(d1) - k * _ncdf(d2)) if kind == "CE" else (k * _ncdf(-d2) - spot * _ncdf(-d1))\n\n\ndef next_tuesday(d: date) -> date:\n    return d + timedelta(days=(1 - d.weekday()) % 7)\n\n\nDDL = """CREATE TABLE backtest_candles_1m (\n    instrument_token INTEGER NOT NULL, ts INTEGER NOT NULL, underlying TEXT NOT NULL,\n    tradingsymbol TEXT NOT NULL, instrument_type TEXT NOT NULL, strike REAL NOT NULL,\n    expiry TEXT NOT NULL, open REAL NOT NULL, high REAL NOT NULL, low REAL NOT NULL,\n    close REAL NOT NULL, volume INTEGER NOT NULL DEFAULT 0, oi INTEGER NOT NULL DEFAULT 0,\n    PRIMARY KEY (instrument_token, ts));\nCREATE INDEX idx_bt1m_sym_ts ON backtest_candles_1m (tradingsymbol, ts);\nCREATE INDEX idx_bt1m_under_exp_ts ON backtest_candles_1m (underlying, expiry, ts);"""\n\n\ndef build_corpus(path: str, sessions: int = 40, seed: int = 7) -> list:\n    rnd = random.Random(seed)\n    conn = sqlite3.connect(path)\n    conn.executescript(DDL)\n    d, spot, token, tokens, rows, days = date(2026, 1, 5), 24000.0, 1000, {}, [], []\n    while len(days) < sessions:\n        if d.weekday() >= 5 or d == date(2026, 1, 26):\n            d += timedelta(days=1)\n            continue\n        days.append(d)\n        ds = ds_of(d)\n        exp = next_tuesday(d)\n        exp_iso = exp.isoformat()\n        exp_ts = ds_of(exp) + (15 * 60 + 30) * 60\n        strikes = None\n        for mod in range(SESSION_OPEN_MIN, 15 * 60 + 30):\n            step = rnd.gauss(0, 3.0)\n            if rnd.random() < 0.02:\n                step += rnd.choice([-1, 1]) * rnd.uniform(25, 60)\n            o, c = spot, spot + step\n            h = max(o, c) + abs(rnd.gauss(0, 1.5))\n            l = min(o, c) - abs(rnd.gauss(0, 1.5))\n            spot = c\n            ts = ds + mod * 60\n            rows.append((256265, ts, "NIFTY", "NIFTYSPOT", "SPOT", 0.0, "", o, h, l, c, 0, 0))\n            if strikes is None:\n                atm = round(spot / 50) * 50\n                strikes = [atm + 50 * i for i in range(-8, 9)]\n            t_years = max((exp_ts - ts) / (365.0 * 86400), 1e-6)\n            for k in strikes:\n                for kind in ("CE", "PE"):\n                    sym = f"NIFTY{exp.strftime(\'%y%m%d\')}{int(k)}{kind}"\n                    if sym not in tokens:\n                        token += 1\n                        tokens[sym] = token\n                    po = max(bs(o, k, t_years, 0.14, kind), 0.05)\n                    pc = max(bs(c, k, t_years, 0.14, kind), 0.05)\n                    ph = max(bs(h if kind == "CE" else l, k, t_years, 0.14, kind), 0.05)\n                    pl = max(bs(l if kind == "CE" else h, k, t_years, 0.14, kind), 0.05)\n                    rows.append((tokens[sym], ts, "NIFTY", sym, kind, float(k), exp_iso,\n                                 round(po, 2), round(max(ph, po, pc), 2), round(min(pl, po, pc), 2),\n                                 round(pc, 2), 100, 1000))\n        d += timedelta(days=1)\n    conn.executemany("INSERT INTO backtest_candles_1m VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)", rows)\n    conn.commit()\n    conn.close()\n    return days\n\n\ntmp = tempfile.mkdtemp()\nDBP = os.path.join(tmp, "backtest.db")\nDAYS = build_corpus(DBP)\nRUN_FROM, RUN_TO = DAYS[5], DAYS[-1]\nprint(f"  corpus: {len(DAYS)} sessions {DAYS[0]}..{DAYS[-1]}")\n\n# a permissive config (lab round-1 shape) so the synthetic walk produces trades\nBASE = {"direction": "BOTH", "disp_atr": 1.0, "fib_gate": 0, "skip_expiry_day": 0,\n        "max_trades_per_day": 3, "entry_until": "14:30", "tp_mode": "rr", "tp_rr": 2.0,\n        "sl_trigger": "touch", "warmup_sessions": 3, "lots": 1}\n\n\ndef run(cfg: dict, **kw):\n    return run_fvg_backtest(db_path=DBP, strategy_id="FVG_V1", underlying="NIFTY",\n                            date_from=RUN_FROM, date_to=RUN_TO, config_override=cfg, **kw)\n\n\nr = run(BASE)\ntr, dg, sm = r["trades"], r["summary"]["diag_fvg"], r["summary"]\ncfgm = _merge_cfg(BASE)\ncheck("run returns a run_id and trades", bool(r["run_id"]) and len(tr) > 0, f"trades={len(tr)} diag={dg}")\ncheck("days iterated", dg["days_total"] == len(DAYS) - 5)\ncheck("every trade closed with a known reason", all(t.exit_reason in ("SL", "BE", "TP", "TIME", "EOD") for t in tr))\ncheck("net == gross − charges (persist surface)", all(abs(t.net_pnl - (t.pnl - t.charges)) < 0.02 for t in tr))\ncheck("exit never before entry", all(t.exit_ts >= t.entry_ts for t in tr))\ncheck("hold_max respected", all(t.hold_min <= cfgm["hold_max"] or t.exit_reason == "EOD" for t in tr))\no_ = sorted(tr, key=lambda t: t.entry_ts)\ncheck("one position at a time", all(b.entry_ts > a.exit_ts for a, b in zip(o_, o_[1:])))\ncheck("qty = lots × 65", all(t.qty == 65 for t in tr))\ncheck("entries inside the window", all(_hhmm(cfgm["entry_from"], 0) <= (t.entry_ts - ds_of(date.fromisoformat(\n    (datetime(1970, 1, 1) + timedelta(seconds=t.entry_ts + IST_OFFSET)).date().isoformat()))) // 60\n    < _hhmm(cfgm["entry_until"], 0) for t in tr))\ncheck("budget: <= max_trades_per_day per session", max(\n    sum(1 for t in tr if (t.entry_ts + IST_OFFSET) // 86400 == k)\n    for k in {(t.entry_ts + IST_OFFSET) // 86400 for t in tr}) <= cfgm["max_trades_per_day"])\ncheck("risk >= sl_min_pts", all(t.risk_pts >= cfgm["sl_min_pts"] - 1e-9 for t in tr))\ncheck("dte attached and >= 0", all(t.dte is not None and t.dte >= 0 for t in tr))\ncheck("summary contract keys", all(k in sm for k in ("total_trades", "wins", "losses", "win_rate", "gross_pnl",\n                                                     "total_charges", "net_pnl", "max_drawdown", "diag_fvg")))\ncheck("scoreboard in diag", all(k in dg for k in ("years", "pos_years", "worst_month", "max_consec_losing_months",\n                                                   "pos_months", "net_pre_split", "net_post_split",\n                                                   "sl_fill_artifact_net", "top5_share_pct")))\ncheck("exit shares sum to 100", abs(sum(dg.get(f"{k}_pnl_share_pct", 0) for k in ("sl", "be", "tp", "time", "eod")) - 100) < 0.5\n      if abs(sm["net_pnl"]) > 1 else True)\ncheck("persist surface: symbol/instrument_type/direction/condition present",\n      all(t.symbol and t.instrument_type in ("CE", "PE") and t.direction == "BUY" and t.condition for t in tr))\nkinds = {t.kind for t in tr}\nprint(f"  setups: {kinds}; exits: { {k: dg[k] for k in (\'sl_exits\', \'tp_exits\', \'time_exits\', \'eod_exits\') } }; net {sm[\'net_pnl\']}")\n\n# sealed defaults run (CE-only, 09:30–11:00, close trigger, tp off, skip expiry)\nrs_ = run({"warmup_sessions": 3})\nds_ = rs_["summary"]["diag_fvg"]\ncheck("sealed defaults run", not rs_.get("aborted") and ds_["days_total"] > 0, str(rs_.get("reason")))\ncheck("sealed: CE only, TP off, expiry days skipped",\n      all(t.instrument_type == "CE" and t.tp is None and t.dte > 0 for t in rs_["trades"]))\ncheck("sealed: DEFAULTS match the bible", DEFAULTS["direction"] == "CE" and DEFAULTS["entry_until"] == "11:00"\n      and DEFAULTS["disp_atr"] == 1.5 and DEFAULTS["sl_trigger"] == "close" and DEFAULTS["tp_mode"] == "off"\n      and DEFAULTS["hold_max"] == 60 and DEFAULTS["skip_expiry_day"] is True and DEFAULTS["fib_gate"] is False\n      and DEFAULTS["max_trades_per_day"] == 1 and DEFAULTS["be_rr"] == 0)\n\n# close trigger: SL/TP exits fill at the NEXT minute\'s option open after a 1m close through the level\nrc = run({**BASE, "sl_trigger": "close"})\nsp_cache = {}\nok_close = len(rc["trades"]) > 0\nconn = sqlite3.connect(DBP)\nconn.row_factory = sqlite3.Row\nfor t in rc["trades"]:\n    if t.exit_reason not in ("SL", "TP"):\n        continue\n    ds = (t.entry_ts + IST_OFFSET) // 86400 * 86400 - IST_OFFSET\n    if t.exit_ts >= ds + _hhmm(cfgm["eod_square_off"], 0) * 60:\n        continue\n    prev = conn.execute("SELECT close FROM backtest_candles_1m WHERE tradingsymbol=\'NIFTYSPOT\' AND ts=?",\n                        (t.exit_ts - 60,)).fetchone()\n    o2 = conn.execute("SELECT open FROM backtest_candles_1m WHERE tradingsymbol=? AND ts=?",\n                      (t.symbol, t.exit_ts)).fetchone()\n    lvl_hit = (prev["close"] <= t.sl or prev["close"] >= t.tp) if t.instrument_type == "CE" else \\\n              (prev["close"] >= t.sl or prev["close"] <= t.tp)\n    if o2 is None or abs(o2["open"] - t.exit_price) > 1e-6 or not lvl_hit:\n        ok_close = False\n        break\ncheck("close-trigger exits fill at next-minute option open", ok_close)\ncheck("close trigger: fill artifact is the trigger-minute close", all(\n    t.net_alt_fill is not None for t in rc["trades"]))\n\n# variants\nrf = run({**BASE, "sl_fill": "close"})\ncheck("sl_fill=close reproduces net_alt_fill of the low-fill run",\n      abs(rf["summary"]["net_pnl"] - dg["net_alt_fill"]) < 1.0,\n      f"{rf[\'summary\'][\'net_pnl\']} vs {dg[\'net_alt_fill\']}")\ncheck("tp_mode=fib runs", run({**BASE, "tp_mode": "fib"})["summary"]["total_trades"] > 0)\ncheck("be_rr variant runs", run({**BASE, "be_rr": 1.0})["summary"]["diag_fvg"]["be_armed"] >= 0)\nrp = run({**BASE, "direction": "PE"})\ncheck("direction=PE yields only PE trades", rp["trades"] and all(t.instrument_type == "PE" for t in rp["trades"]))\nrd = run({**BASE, "dte_min": 3})\ncheck("dte_min=3 keeps only 3–4DTE sessions", rd["trades"] and all(t.dte >= 3 for t in rd["trades"])\n      and rd["summary"]["diag_fvg"]["days_skipped_dte"] > 0)\nrm = run({**BASE, "dte_lot_mult": "0:0, 4:2"})\ncheck("dte_lot_mult: 0DTE skipped, 4DTE doubled", rm["trades"] and all(t.dte != 0 for t in rm["trades"])\n      and all(t.qty == (130 if t.dte == 4 else 65) for t in rm["trades"])\n      and rm["summary"]["diag_fvg"]["dte_skipped_days"] > 0)\nra = run({**BASE, "entry_mode": "fixed", "direction": "CE"})\ncheck("control A: one CE at 10:00 every session, fixed 30-pt stop",\n      len(ra["trades"]) == len(DAYS) - 5 and all(t.kind == "CTRL" and t.instrument_type == "CE"\n                                                  and abs(t.risk_pts - 30) < 1e-9 for t in ra["trades"]))\nrb = run({**BASE, "entry_mode": "matched", "direction": "CE"})\nrF = run({**BASE, "direction": "CE"})\nfd = {(t.entry_ts + IST_OFFSET) // 86400 for t in rF["trades"]}\ncd = {(t.entry_ts + IST_OFFSET) // 86400 for t in rb["trades"]}\ncheck("control B: fixed entries only on signal days", 0 < len(cd) <= len(ra["trades"]) and fd <= cd)\nfor bad, key in (({"entry_from": "12:00", "entry_until": "11:00"}, "time order"),\n                 ({"tf": 0}, "tf"), ({"dte_min": 5, "dte_max": 1}, "dte"),\n                 ({"strike_offset": 40}, "strike_offset")):\n    rr_ = run({**BASE, **bad})\n    check(f"abort on bad {key}", rr_.get("aborted") and rr_["run_id"] is None, str(rr_.get("reason")))\nprog = []\nrun(BASE, progress_cb=lambda p: prog.append(p))\ncheck("progress callback fires per day", len(prog) == len(DAYS) - 5)\ncalls = {"n": 0}\n\n\ndef _cancel():\n    calls["n"] += 1\n    return calls["n"] > 3\n\n\nrcx = run(BASE, cancel_cb=_cancel)\ncheck("cancel stops the loop early", rcx["summary"]["diag_fvg"]["days_total"] <= 3)\n\n# ═════════════════════════════════ 3. lab parity ═════════════════════════\nprint("── lab parity ──")\nLAB = os.path.join(REPO, "tools", "lab", "fvg")\nif os.path.isfile(os.path.join(LAB, "fvg_fib_backtest.py")):\n    sys.path.insert(0, LAB)\n    import importlib\n    lab = importlib.import_module("fvg_fib_backtest")\n    lab_corpus = lab.Corpus(DBP, "NIFTY")\n    lab_corpus.load_spot(RUN_FROM - timedelta(days=30), RUN_TO)\n    lab_corpus.load_expiry_ranges()\n    for label, cfg in (("round-1 shape", BASE),\n                       ("sealed (tp rr for lab)", {"warmup_sessions": 3, "tp_mode": "rr", "tp_rr": 8.0}),\n                       ("close-trigger + fib + ifvg off", {**BASE, "sl_trigger": "close", "fib_gate": 1, "trade_ifvg": 0}),\n                       ("control matched", {**BASE, "entry_mode": "matched", "direction": "CE"})):\n        app_cfg = _merge_cfg(cfg)\n        lab_cfg = lab.merge_cfg({k: (int(v) if isinstance(v, bool) else v)\n                                 for k, v in app_cfg.items() if k in lab.DEFAULTS})\n        lab_res = lab.run(lab_corpus, lab_cfg, RUN_FROM, RUN_TO)\n        app_res = run(cfg)\n        a = [(t.entry_ts, t.symbol, t.entry_price, t.exit_ts, t.exit_price, t.exit_reason, t.net_pnl, t.qty)\n             for t in app_res["trades"]]\n        b = [(t.entry_ts, t.tradingsymbol, t.entry_price, t.exit_ts, t.exit_price, t.exit_reason, t.net, t.qty)\n             for t in lab_res["trades"]]\n        check(f"parity [{label}]: {len(a)} trades identical", len(a) > 0 and a == b,\n              f"app={len(a)} lab={len(b)} first_diff={next(((x, y) for x, y in zip(a, b) if x != y), None)}")\nelse:\n    print("  SKIP  tools/lab/fvg not present — parity not checked (fine on a CI checkout)")\n\nprint()\nif FAILS:\n    print("FAILED:", FAILS)\n    sys.exit(1)\nprint("ALL PASS")\nsys.exit(0)\n', 'docs/FVG_V1_BIBLE.md': '# FVG_V1 — "Fissure" — Strategy Bible\n\n**Status:** sealed 2026-09-16 (backtest); paper next.\n**Fence:** `FVG_V1_20260916` · lab fence `FVG_LAB_20260916` (`tools/lab/fvg/`)\n**Author:** Anbu (operator/decisions) + Claude (design/code), one session, 2026-09-16.\n**Origin:** an experiment — "build a NIFTY intraday option-*buying* strategy from\nindicators the app has never used (FVG, IFVG, Fibonacci), then fine-tune it from\nthe backtest". Five rounds later one configuration survived; most of the original\nidea did not.\n\n---\n\n## 1. What it is\n\nLong NIFTY weekly **CE**, bought at the **retest of a morning displacement gap**,\nwith a **structural spot stop** and a **timed exit**.\n\n* **Signal timeframe:** 5-minute bars from 1-minute NIFTY spot on the 09:15 grid.\n* **Fair Value Gap (FVG):** three consecutive 5m candles where `c[i].low > c[i-2].high`\n  (bullish). The band `[c[i-2].high, c[i].low]` is the gap. Only gaps whose middle\n  candle **body ≥ 1.5 × ATR(14)** and whose width ≥ 0.15 × ATR count.\n* **Inverse FVG (IFVG):** a gap that is violated by a 5m **close** through it flips\n  polarity (old bullish gap → bearish band and vice versa). The retest of the\n  inverted band is traded in the new direction. (Only the CE side is sealed, so in\n  practice IFVG longs come from violated *bearish* gaps.)\n* **Entry trigger (1m):** price comes back *into* the band, then a 1m **green close\n  back above** it. Buy the ATM weekly CE at the **next 1m open**. A gap is used once.\n* **Stop:** gap-band bottom − 0.1 ATR, on **spot**. Floor 15 pts (widened if closer),\n  skip if > 3 ATR. Trigger = **1m close** through the level; the option is sold at\n  the **next minute\'s open** (wick-immune, ORB_SLTRIG convention).\n* **Exit:** sold at the 1m close **60 minutes** after entry, or EOD 15:20. **No target.**\n* **Window:** entries 09:30–11:00 only. **Max 1 trade/day.** **Expiry day skipped.**\n* Costs: locked v4 Zerodha charges (`charges_model.py`).\n\nThe engine (`fvg_v1_engine.py`) is pure and decides everything from closed bars,\nso a live engine can replay it incrementally (parity-by-construction).\n\n## 2. Sealed config (`DEFAULTS` in `backtest_fvg_runner.py`)\n\n```\ntf 5 · atr_len 14 · disp_atr 1.5 · gap_min_atr 0.15 · fib_gate off\ntrade_fvg on · trade_ifvg on · direction CE · gap_max_age 12 · max_gaps 6\nstrike_offset 0 · premium band off · lots 1 (index lot)\nsl_min_pts 15 · sl_max_atr 3 · sl_buf_atr 0.1 · sl_trigger close · sl_fill low (inert)\ntp_mode off · be_rr 0 · hold_max 60\nentry_from 09:30 · entry_until 11:00 · eod_square_off 15:20\nmax_trades_per_day 1 · skip_expiry_day on · dte 0–99 · warmup_sessions 5\n```\n\n**Result, 10 lots, 2020-01 → 2026-09 (lab round 5, row 1):**\n175 trades · years **+6/7** (2020 −₹27k on 5 trades) · worst month **−₹41.6k** ·\n4 consecutive losing months · 32/61 months positive · maxDD **₹1.18L** ·\nnet **₹5.49L** · net/DD **4.64** · 2020–23 ₹2.95L / 2024–26 ₹2.54L ·\nSL-fill artifact ₹12k · win rate ~42% · avg win ₹16k / avg loss ₹8k.\n\n**Calibration to expect in paper:** ~₹80k/year at 10 lots, one losing month a\nquarter, up to nine losing trades in a row. Capital footprint is premium-only\n(~₹65k–1L per trade). A small, capital-light morning strategy — not a fleet anchor.\n\n## 3. The five rounds (all 10 lots, 2020–2026, full corpus)\n\n| Round | Question | Result |\n|---|---|---|\n| 1 — v1 as designed | 5m, disp 1.0, fib on, FVG+IFVG, both sides, 09:30–14:30, 3/day, 2R, hold 60, touch-trigger low-fill | **Falsified.** 3,061 trades, gross ₹63k, charges ₹5.98L, net −₹5.35L, 2/7 years, 2023–26 all negative. SL-fill convention worth ₹16.7L (low −₹5.35L vs close +₹11.37L). |\n| 2 — pre-registered filters | sl_trigger × dte≥3 × until 11:00 × CE-only × fib (32 runs) | One config cleared the bar: CE-only, until 11:00, close trigger, fib off — 225 trades, 6/7 years, ₹2.20L/₹2.29L split, net ₹4.49L, DD ₹1.34L. Every BOTH row lost; entries to 14:30 lose 2024–26. |\n| 3 — anatomy + plateau | top-5 concentration, losing year, 27 neighbours (disp × tp_rr × until) | Net without top-5 winners +₹1.78L; all neighbours net-positive with ≥5/7 years; disp 1.2 degrades post-2024, disp ≥1.5 holds. TIME exits carry the net; 3R hit 18/225. |\n| 4 — exit shape | hold 30–120 × tp 3/8 × be × skip-expiry (40 runs) | Hold is a rising plateau (30m ₹2.5L → 120m ₹7.4L, DD flat ₹1.2–1.3L). Target decorative. Breakeven rejected. Skip-expiry improves worst month (−₹63k → −₹42k) at hold ≤60. |\n| 5 — control | strategy vs fixed 10:00 entry every day vs fixed 10:00 on signal days | Strategy ₹5.5L / DD ₹1.2L. Controls: every day −₹7.1L to −₹9.9L (0–2 years positive); matched days −₹1.8L to −₹2.2L (DD ₹3–4.3L). **The edge is entry location, not day selection or morning drift.** |\n\n## 4. Falsification record — tested and rejected, do not rebuild\n\n* **PE side / BOTH direction** — negative carry in every configuration (round 1 PE −₹10L; round 2 every BOTH row negative).\n* **Entries after 11:00** — 2024–26 negative (−₹1.2L at 14:30 vs +₹2.5L at 11:00 on the same rules).\n* **Fibonacci golden-pocket gate (0.382–0.786)** — never improved worst month or DD; cost 10–12% of trades and ₹20–40k of net in every pair, two rounds. The one indicator the experiment was named after adds nothing.\n* **Displacement 1.0–1.2 ATR** — round 1 (1.0) falsified outright; 1.2 makes in-sample net but +₹20–44k out-of-sample (2024–26) vs +₹1.4–2.0L for 1.5.\n* **Breakeven stop at +1R** — −₹0.6–1.5L at every hold, DD equal or worse.\n* **Profit target (2R/3R/4R/8R)** — indistinguishable from off; 18/225 hits at 3R.\n* **Touch-trigger stop with option-low fill** — not wrong, but the result is then a fill-model artifact (₹16.7L swing). Close trigger sealed; if touch is ever used, compare low vs close fill first.\n* **Fixed-time entry (10:00) with or without gap-day selection** — both controls negative (round 5).\n\nDocumented variants, not sealed: **hold 90** (₹7L, net/DD 5.75, but 5/7 years and −₹50.6k worst month); **dte ≥ 3** (net/DD 4.29 on 94 trades, too sparse); **disp 2.0** (7/7 years, ₹3.3L, 65 trades).\n\n## 5. Tripwires to read on every run (`summary.diag_fvg`)\n\n* `time_pnl_share_pct` — the timed exit carries the net **by design**; net migrating into TP/SL means a different strategy.\n* `sl_fill_artifact_net` — ≈ 0 with the sealed close trigger; anything else is a red flag.\n* `top5_share_pct`, `net_without_top5` — 60% / +₹1.78L on the sealed run; the latter must stay positive.\n* `years`, `pos_years`, `net_pre_split`, `net_post_split`, `worst_month`, `max_consec_losing_months` — the scoreboard in priority order.\n* `fvg_net` vs `ifvg_net`, `entry_hour_hist`, DTE breakdown (0DTE was the only losing DTE).\n* `sig_sl_widened` — share of stops at the 15-pt floor (18% sealed); a jump means the gaps got thinner.\n\n## 6. Known limits and open items\n\n* **Long-only exposure.** The strategy holds a CE for an hour on ~35 mornings a year. 2020–26 is a rising index; six positive years and a negative control are the evidence it is not pure beta, but a bear regime has not been observed. Paper is the next test.\n* **Special sessions.** Sessions are "days with SPOT prints in the corpus" — a Saturday special session is traded like any other. Live must use the NSE calendar the fleet already uses.\n* **BANKNIFTY** untested (index-only runner supports it if `BANKNIFTYSPOT` rows exist).\n* **Strike offset +1** untested.\n* **Live/paper integration** not built: needs the 1m→5m resample + continuous ATR replayed from Kite candles with VET_V1 as donor; entry order at the 1m open after a rejection close; stop check on 1m closes; hold timer; the fleet\'s DTE skip via `dte_lot_mult`.\n\n## 7. How to reproduce\n\n```\n# lab (standalone, reads the corpus directly)\ncd tools/lab/fvg\npython3 fvg_fib_backtest.py --lots 10 --months \\\n  --set direction=CE entry_until=11:00 sl_trigger=close fib_gate=0 disp_atr=1.5 \\\n        max_trades_per_day=1 tp_rr=8 skip_expiry_day=1\n\n# app: Backtest page → FVG V1 → Run (defaults are the sealed config)\n# parity: cd backend && PYTHONPATH=$PWD python3 app/backtest/fvg/test_fvg_runner_sim.py\n```\n', 'tools/lab/fvg/fvg_fib_engine.py': '# fvg_fib_engine.py\n#\n# ── FVG_V1 ("Fissure") ── Fair Value Gap / Inverse FVG pullback entries with a\n# Fibonacci golden-pocket confluence gate, on NIFTY SPOT, for weekly option\n# BUYING. PURE MODULE: no DB, no clock, no I/O. Everything here is decided\n# from bars already closed, so it can later be re-run incrementally by a live\n# engine (parity-by-construction, same as STFC/ORB/VET).\n#\n# Fence: FVG_LAB_20260916   (lab only — NOT wired into the app)\n#\n# ── THE IDEA ──────────────────────────────────────────────────────────────\n#   A Fair Value Gap is a 3-candle displacement: candle[i].low > candle[i-2]\n#   .high (bullish) leaves an un-traded price band [c[i-2].high, c[i].low].\n#   The thesis (ICT school): the impulse that left the gap is institutional\n#   participation; price tends to return INTO the gap ("fill the imbalance")\n#   and continue in the impulse direction. We do NOT buy the gap blindly —\n#   we wait for price to (a) come back into the band and (b) print a 1m\n#   rejection close back above the band. That converts a "level" into a\n#   "confirmed level", which is where the option is bought.\n#\n#   Inverse FVG (IFVG): a gap that is VIOLATED by a tf-bar close through it\n#   flips polarity — old bullish gap becomes a bearish supply band. We trade\n#   the retest of the inverted band in the new direction.\n#\n#   Fibonacci gate (FVG setups only): the gap must sit inside the 0.382–0.786\n#   retracement of the impulse leg (swing extreme before the displacement →\n#   impulse extreme). A gap outside that band is either too shallow (weak\n#   displacement) or too deep (the leg already failed).\n#\n# ── DECISIONS (D1–D7, locked before the runner) ───────────────────────────\n#   D1  Signal timeframe `tf` (default 5m) built from 1m SPOT, session grid\n#       09:15. FVG detection and inversion are decided on CLOSED tf bars.\n#   D2  Displacement filter: the middle candle body >= disp_atr × ATR(tf)\n#       and the gap width >= gap_min_atr × ATR. ATR is Wilder RMA over\n#       `atr_len` tf bars and is CONTINUOUS across sessions (warm-up needed).\n#   D3  Trigger on 1m bars only AFTER the gap\'s birth bar has closed:\n#         bull FVG:  touched when 1m low <= top; trigger when touched AND\n#                    1m close > top AND close > open (rejection candle).\n#         bear FVG:  mirror.\n#         IFVG (inverted bull → bearish band): touched when 1m high >= bottom;\n#                    trigger when touched AND 1m close < bottom AND close < open.\n#       Entry is at the NEXT 1m open (runner). A gap is used at most once.\n#   D4  Structural stop: bull FVG stop = gap bottom − buf; bear = top + buf;\n#       IFVG stops on the far side of the band. buf = sl_buf_atr × ATR.\n#   D5  Inversion: bull gap inverts on a tf CLOSE below its bottom; an\n#       inverted band dies on a tf close back through its far side. Gaps\n#       expire `gap_max_age` tf bars after birth (or after inversion).\n#   D6  Gaps are INTRADAY only (list cleared at day start). Cross-day gaps\n#       are a separate hypothesis; not in v1.\n#   D7  Fib gate applies to FVG setups; IFVG has no clean impulse leg and\n#       is exempt (explicitly counted so the share is visible).\n#\n# ── FALSIFICATION TRIPWIRES (runner prints all of these) ──────────────────\n#   * sl_fill_artifact: net(SL fills at option low) vs net(SL at close) —\n#     P&L must not be a fill-convention artifact (ORB_SLFILL doctrine).\n#   * time/eod share of net: if the timed exit carries the net the edge is\n#     "hold after a gap", not the level.\n#   * FVG vs IFVG net, CE vs PE net, per-year signs, per-hour, per-DTE.\n#   * sl_in_entry_minute: stops hit in the fill minute = noise stop (STFC scar).\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Optional\n\nSESSION_OPEN_MIN = 9 * 60 + 15         # 09:15 IST, minute-of-day\nIST_OFFSET = 5 * 3600 + 30 * 60\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  BARS\n# ─────────────────────────────────────────────────────────────────────────\n@dataclass\nclass Bar:\n    ts: int\n    open: float\n    high: float\n    low: float\n    close: float\n    end_min: int = 0                   # tf bars: last minute-of-day inside the bar\n    start_min: int = 0\n\n\ndef resample_session(bars_1m: List[Bar], *, day_start_epoch: int,\n                     tf_minutes: int) -> List[Bar]:\n    """Bucket 1m bars onto the 09:15 grid (identical to the STFC helper)."""\n    out: Dict[int, dict] = {}\n    for b in bars_1m:\n        mod = (b.ts - day_start_epoch) // 60\n        if mod < SESSION_OPEN_MIN:\n            continue\n        bucket = (mod - SESSION_OPEN_MIN) // tf_minutes\n        bts = day_start_epoch + (SESSION_OPEN_MIN + bucket * tf_minutes) * 60\n        cur = out.get(bts)\n        if cur is None:\n            out[bts] = {"o": b.open, "h": b.high, "l": b.low, "c": b.close,\n                        "s": SESSION_OPEN_MIN + bucket * tf_minutes,\n                        "e": SESSION_OPEN_MIN + (bucket + 1) * tf_minutes - 1}\n        else:\n            cur["h"] = max(cur["h"], b.high)\n            cur["l"] = min(cur["l"], b.low)\n            cur["c"] = b.close\n    return [Bar(ts, v["o"], v["h"], v["l"], v["c"], v["e"], v["s"])\n            for ts, v in sorted(out.items())]\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  ATR — Wilder RMA, stateful, continuous across sessions\n# ─────────────────────────────────────────────────────────────────────────\nclass ATR:\n    def __init__(self, length: int):\n        if length < 1:\n            raise ValueError("atr length must be >= 1")\n        self.length = int(length)\n        self.n = 0\n        self.tr_sum = 0.0\n        self.value: Optional[float] = None\n        self.prev_close: Optional[float] = None\n\n    def update(self, b: Bar) -> Optional[float]:\n        tr = (b.high - b.low) if self.prev_close is None else max(\n            b.high - b.low, abs(b.high - self.prev_close), abs(b.low - self.prev_close))\n        if self.n < self.length - 1:\n            self.tr_sum += tr\n        elif self.n == self.length - 1:\n            self.tr_sum += tr\n            self.value = self.tr_sum / self.length\n        else:\n            self.value = (self.value * (self.length - 1) + tr) / self.length\n        self.n += 1\n        self.prev_close = b.close\n        return self.value\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  GAPS\n# ─────────────────────────────────────────────────────────────────────────\n@dataclass\nclass Gap:\n    side: str                          # \'BULL\' | \'BEAR\'   (polarity NOW)\n    top: float\n    bottom: float\n    born_idx: int                      # tf index of the third candle\n    born_end_min: int\n    atr_at_birth: float\n    leg_low: float\n    leg_high: float\n    fib_ok: bool\n    state: str = "FRESH"               # FRESH | INVERTED | DEAD\n    age: int = 0                       # tf bars since birth / inversion\n    touched: bool = False\n    used: bool = False\n    inverted_from: Optional[str] = None\n    gid: int = 0\n\n    @property\n    def kind(self) -> str:\n        return "IFVG" if self.state == "INVERTED" else "FVG"\n\n\n@dataclass(frozen=True)\nclass Signal:\n    trigger_min: int                   # minute-of-day of the rejection close\n    side: str                          # \'CE\' | \'PE\'\n    kind: str                          # \'FVG\' | \'IFVG\'\n    sl_level: float                    # structural stop on SPOT\n    zone_top: float\n    zone_bottom: float\n    leg_target: Optional[float]        # fib 1.0 target (FVG only) else None\n    atr: float\n    gid: int\n\n\n@dataclass\nclass EngineConfig:\n    atr_len: int = 14\n    disp_atr: float = 1.0              # middle-candle body >= disp_atr × ATR\n    gap_min_atr: float = 0.15          # gap width >= gap_min_atr × ATR\n    fib_gate: bool = True\n    fib_lo: float = 0.382\n    fib_hi: float = 0.786\n    fib_lookback: int = 10             # tf bars before the displacement candle\n    sl_buf_atr: float = 0.10\n    gap_max_age: int = 12              # tf bars (12 × 5m = 60 min)\n    trade_fvg: bool = True\n    trade_ifvg: bool = True\n    direction: str = "BOTH"            # BOTH | CE | PE\n    max_gaps: int = 6                  # newest gaps kept per day\n\n\ndef _fib_overlap(cfg: EngineConfig, side: str, zone_top: float,\n                 zone_bottom: float, leg_low: float, leg_high: float) -> bool:\n    rng = leg_high - leg_low\n    if rng <= 0:\n        return False\n    if side == "BULL":\n        hi_px = leg_high - cfg.fib_lo * rng    # shallower retrace (higher price)\n        lo_px = leg_high - cfg.fib_hi * rng    # deeper retrace\n    else:\n        lo_px = leg_low + cfg.fib_lo * rng\n        hi_px = leg_low + cfg.fib_hi * rng\n    return zone_top >= lo_px and zone_bottom <= hi_px\n\n\nclass FvgEngine:\n    """Per-day setup machine. Call new_day() at the start of every session,\n    on_tf_close() after every closed tf bar, on_minute() for every 1m bar\n    that lies AFTER the tf bar it belongs to has been born (the runner\n    guarantees ordering — see runner R1)."""\n\n    def __init__(self, cfg: EngineConfig, atr: ATR):\n        self.cfg = cfg\n        self.atr = atr\n        self.gaps: List[Gap] = []\n        self.bars: List[Bar] = []\n        self._gid = 0\n        self.diag: Dict[str, int] = {}\n\n    # ── diagnostics ──\n    def _bump(self, k: str, n: int = 1) -> None:\n        self.diag[k] = self.diag.get(k, 0) + n\n\n    def new_day(self) -> None:\n        self.gaps = []\n        self.bars = []\n\n    # ── tf bar closed ──\n    def on_tf_close(self, b: Bar) -> None:\n        self.bars.append(b)\n        atr = self.atr.update(b)\n        i = len(self.bars) - 1\n        # 1. age / inversion / death of existing gaps\n        for g in self.gaps:\n            if g.state == "DEAD":\n                continue\n            g.age += 1\n            if g.age > self.cfg.gap_max_age:\n                g.state = "DEAD"\n                self._bump("gap_expired")\n                continue\n            if g.state == "FRESH":\n                if (g.side == "BULL" and b.close < g.bottom) or \\\n                   (g.side == "BEAR" and b.close > g.top):\n                    g.state = "INVERTED"\n                    g.inverted_from = g.side\n                    g.side = "BEAR" if g.side == "BULL" else "BULL"\n                    g.age = 0\n                    g.touched = False\n                    g.used = False\n                    self._bump("gap_inverted")\n            elif g.state == "INVERTED":\n                # reclaimed through the far side → band is spent\n                if (g.side == "BEAR" and b.close > g.top) or \\\n                   (g.side == "BULL" and b.close < g.bottom):\n                    g.state = "DEAD"\n                    self._bump("ifvg_reclaimed")\n        # 2. detect a new gap on the last three closed bars\n        if atr is None or i < 2:\n            return\n        c0, c1, c2 = self.bars[i - 2], self.bars[i - 1], self.bars[i]\n        body = abs(c1.close - c1.open)\n        side = None\n        if c2.low > c0.high and c1.close > c1.open:\n            side, top, bottom = "BULL", c2.low, c0.high\n        elif c2.high < c0.low and c1.close < c1.open:\n            side, top, bottom = "BEAR", c0.low, c2.high\n        if side is None:\n            return\n        self._bump("gap_raw")\n        if body < self.cfg.disp_atr * atr:\n            self._bump("gap_rej_displacement")\n            return\n        if (top - bottom) < self.cfg.gap_min_atr * atr:\n            self._bump("gap_rej_width")\n            return\n        lb = max(0, i - 1 - self.cfg.fib_lookback)\n        seg = self.bars[lb:i - 1] or [c1]\n        if side == "BULL":\n            leg_low = min(x.low for x in seg + [c1])\n            leg_high = max(c1.high, c2.high)\n        else:\n            leg_high = max(x.high for x in seg + [c1])\n            leg_low = min(c1.low, c2.low)\n        fib_ok = _fib_overlap(self.cfg, side, top, bottom, leg_low, leg_high)\n        self._bump("gap_fib_ok" if fib_ok else "gap_fib_reject")\n        self._gid += 1\n        g = Gap(side=side, top=top, bottom=bottom, born_idx=i,\n                born_end_min=c2.end_min, atr_at_birth=atr,\n                leg_low=leg_low, leg_high=leg_high, fib_ok=fib_ok, gid=self._gid)\n        self.gaps.append(g)\n        self._bump("gap_born_bull" if side == "BULL" else "gap_born_bear")\n        live = [x for x in self.gaps if x.state != "DEAD"]\n        if len(live) > self.cfg.max_gaps:\n            for x in live[:-self.cfg.max_gaps]:\n                x.state = "DEAD"\n                self._bump("gap_evicted")\n\n    # ── 1m bar (after its tf bar\'s predecessors have closed) ──\n    def on_minute(self, m: Bar, mod: int) -> Optional[Signal]:\n        cfg = self.cfg\n        for g in self.gaps:\n            if g.state == "DEAD" or g.used or g.born_end_min >= mod:\n                continue\n            is_ifvg = g.state == "INVERTED"\n            if is_ifvg and not cfg.trade_ifvg:\n                continue\n            if not is_ifvg and not cfg.trade_fvg:\n                continue\n            if not is_ifvg and cfg.fib_gate and not g.fib_ok:\n                continue\n            if g.side == "BULL":\n                if cfg.direction == "PE":\n                    continue\n                if not g.touched and m.low <= g.top:\n                    g.touched = True\n                    self._bump("touch_bull")\n                if g.touched and m.close > g.top and m.close > m.open:\n                    g.used = True\n                    buf = cfg.sl_buf_atr * g.atr_at_birth\n                    self._bump("trig_ifvg" if is_ifvg else "trig_fvg")\n                    return Signal(trigger_min=mod, side="CE", kind=g.kind,\n                                  sl_level=g.bottom - buf, zone_top=g.top,\n                                  zone_bottom=g.bottom,\n                                  leg_target=None if is_ifvg else g.leg_high,\n                                  atr=g.atr_at_birth, gid=g.gid)\n            else:\n                if cfg.direction == "CE":\n                    continue\n                if not g.touched and m.high >= g.bottom:\n                    g.touched = True\n                    self._bump("touch_bear")\n                if g.touched and m.close < g.bottom and m.close < m.open:\n                    g.used = True\n                    buf = cfg.sl_buf_atr * g.atr_at_birth\n                    self._bump("trig_ifvg" if is_ifvg else "trig_fvg")\n                    return Signal(trigger_min=mod, side="PE", kind=g.kind,\n                                  sl_level=g.top + buf, zone_top=g.top,\n                                  zone_bottom=g.bottom,\n                                  leg_target=None if is_ifvg else g.leg_low,\n                                  atr=g.atr_at_birth, gid=g.gid)\n        return None\n\n\ndef session_signals(engine: FvgEngine, bars_1m: List[Bar], *,\n                    day_start_epoch: int, tf_minutes: int) -> List[Signal]:\n    """Walk one session causally: for each tf bar, run its 1m bars through\n    the trigger machine (gaps from EARLIER tf bars only), then close the\n    tf bar (detection). Returns every signal the day produced; the runner\n    decides which are tradeable (position, budget, window)."""\n    bars_tf = resample_session(bars_1m, day_start_epoch=day_start_epoch,\n                               tf_minutes=tf_minutes)\n    by_min = {(b.ts - day_start_epoch) // 60: b for b in bars_1m}\n    sigs: List[Signal] = []\n    engine.new_day()\n    for tb in bars_tf:\n        for mod in range(tb.start_min, tb.end_min + 1):\n            m = by_min.get(mod)\n            if m is None:\n                continue\n            s = engine.on_minute(m, mod)\n            if s is not None:\n                sigs.append(s)\n        engine.on_tf_close(tb)\n    return sigs\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  helpers shared with the runner\n# ─────────────────────────────────────────────────────────────────────────\ndef strike_step(strikes) -> float:\n    s = sorted({float(x) for x in strikes if x is not None})\n    gaps = [b - a for a, b in zip(s, s[1:]) if b - a > 0]\n    return min(gaps) if gaps else 50.0\n\n\ndef atm_strike(spot: float, step: float) -> float:\n    return round(spot / step) * step\n', 'tools/lab/fvg/fvg_fib_backtest.py': '#!/usr/bin/env python3\n# fvg_fib_backtest.py\n#\n# ── FVG_V1 LAB RUNNER ── standalone, reads ~/.scalp-app/backtest/backtest.db\n# directly (table backtest_candles_1m). NOT wired into the app: this is the\n# falsify-first stage. If a config survives the scoreboard here, it gets an\n# STFC-style runner + SweepBuilder axes as a separate apply script.\n#\n# Fence: FVG_LAB_20260916\n#\n# ── RUNNER DECISIONS (R1–R6) ──────────────────────────────────────────────\n#   R1  Causality: engine sees 1m bars of tf bar k only after tf bars < k\n#       closed; entry fills at the 1m OPEN of trigger_min + 1 (option AND\n#       spot). No unfinished-bar reads.\n#   R2  Contract: front weekly expiry = the smallest expiry >= day that has\n#       prints on that day (era-agnostic, holiday-shift-proof); if its DTE\n#       exceeds `max_dte_sessions` the day is counted uncovered, not traded.\n#       ATM from entry_spot (step inferred from the chain) shifted\n#       strike_offset steps OTM; nearest strike with a print at the fill\n#       minute (fallback counted). Same side as the signal (CE/PE).\n#   R3  Risk: stop is the engine\'s structural SPOT level. risk = |entry_spot\n#       − sl|. If risk < sl_min_pts the stop is WIDENED to sl_min_pts\n#       (counted); if risk > sl_max_atr × ATR the signal is SKIPPED\n#       (counted). tp_mode rr: target = entry ± tp_rr × risk (spot);\n#       tp_mode fib: target = the impulse extreme (fib 1.0) when it is\n#       >= tp_fib_min_rr × risk away, else rr fallback (counted).\n#   R4  Exits per minute, pessimistic order (stop, target, breakeven update,\n#       time, EOD). Spot-touch triggers; the option fills on its OWN 1m bar:\n#       SL at option LOW (sl_fill=low, default, ORB convention) or close;\n#       TP at option CLOSE. Both in one minute → SL. Time exit after\n#       hold_max minutes at close; EOD square-off at eod_square_off close.\n#       A missing option bar leaves the last mark (counted stale).\n#       Optional breakeven: when spot has moved be_rr × risk in favour the\n#       stop moves to entry_spot (0 = off).\n#   R5  Budgets: one position at a time (signals inside a position are\n#       skipped, counted); max_trades_per_day; entries only inside\n#       [entry_from, entry_until); optional daily loss stop in R (0 = off).\n#   R6  ATR warms on `warmup_sessions` sessions before date_from (no trades).\n#\n# ── USAGE ─────────────────────────────────────────────────────────────────\n#   python3 fvg_fib_backtest.py --from 2020-01-01 --to 2026-09-15\n#   python3 fvg_fib_backtest.py --lots 10 --set tf=3 rr=3 hold_max=45\n#   python3 fvg_fib_backtest.py --grid "tf=3,5;disp_atr=0.8,1.2;tp_rr=1.5,2,3"\n#   python3 fvg_fib_backtest.py --export /tmp/fvg_trades.csv\n#   python3 fvg_fib_backtest.py --db /path/to/backtest.db --years\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport itertools\nimport os\nimport sqlite3\nimport sys\nimport time\nfrom dataclasses import dataclass, asdict\nfrom datetime import date, datetime, timedelta\nfrom pathlib import Path\nfrom typing import Dict, List, Optional, Tuple\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nfrom fvg_fib_engine import (Bar, ATR, EngineConfig, FvgEngine, Signal,   # noqa: E402\n                            session_signals, strike_step, atm_strike,\n                            IST_OFFSET, SESSION_OPEN_MIN)\n\nINDEX_LOTS = {"NIFTY": 65, "BANKNIFTY": 35}\nSPLIT_YEAR = "2024"                    # split-half boundary used by the fleet (2020–23 vs 2024–26)\nSPOT_SYMBOL = {"NIFTY": "NIFTYSPOT", "BANKNIFTY": "BANKNIFTYSPOT"}\n\nDEFAULTS: dict = {\n    # engine (D1–D7)\n    "tf": 5, "atr_len": 14, "disp_atr": 1.0, "gap_min_atr": 0.15,\n    "fib_gate": 1, "fib_lo": 0.382, "fib_hi": 0.786, "fib_lookback": 10,\n    "sl_buf_atr": 0.10, "gap_max_age": 12, "trade_fvg": 1, "trade_ifvg": 1,\n    "direction": "BOTH", "max_gaps": 6,\n    # execution (R2–R6)\n    "strike_offset": 0, "premium_min": 0.0, "premium_max": 0.0,\n    "lots": 1, "max_dte_sessions": 7,\n    "sl_min_pts": 15.0, "sl_max_atr": 3.0, "sl_fill": "low", "sl_trigger": "touch",\n    "dte_min": 0, "dte_max": 99,\n    "tp_mode": "rr", "tp_rr": 2.0, "tp_fib_min_rr": 1.0,\n    "be_rr": 0.0, "hold_max": 60,\n    "entry_from": "09:30", "entry_until": "14:30", "eod_square_off": "15:20",\n    "max_trades_per_day": 3, "daily_loss_r": 0.0,\n    "warmup_sessions": 5, "skip_expiry_day": 0,\n    # ── control experiment (round 5) ── entry_mode:\n    #   fvg      the strategy (default)\n    #   fixed    CONTROL A: buy the same side at fixed_entry_time EVERY session,\n    #            stop fixed_sl_pts below/above entry spot, same exits — the\n    #            "morning drift" baseline with no setup at all\n    #   matched  CONTROL B: same as fixed but ONLY on sessions where the FVG\n    #            strategy would have had a tradeable signal — isolates the\n    #            value of the ENTRY TIMING from the value of DAY SELECTION\n    "entry_mode": "fvg", "fixed_entry_time": "10:00", "fixed_sl_pts": 30.0,\n}\n\n# ── charges: LOCKED v4 parity with backend/app/backtest/charges/charges_model.py ──\nBROKERAGE, STT_SELL, EXCHANGE, SEBI, STAMP, GST = 40.0, 0.0015, 0.0003553, 0.000001, 0.00003, 0.18\n\n\ndef charges_long(entry: float, exit_: float, qty: int) -> float:\n    if not entry or not exit_ or not qty:\n        return 0.0\n    buy_v, sell_v = entry * qty, exit_ * qty\n    to = buy_v + sell_v\n    ex, se = EXCHANGE * to, SEBI * to\n    return round((BROKERAGE + STT_SELL * sell_v + ex + se + STAMP * buy_v\n                  + GST * (BROKERAGE + ex + se)) * 100) / 100\n\n\ndef _hhmm(s: str) -> int:\n    h, m = str(s).split(":")\n    return int(h) * 60 + int(m)\n\n\ndef day_start_epoch(d: date) -> int:\n    return int((datetime(d.year, d.month, d.day) - datetime(1970, 1, 1)).total_seconds()) - IST_OFFSET\n\n\ndef epoch_day(ts: int) -> date:\n    return (datetime(1970, 1, 1) + timedelta(seconds=ts + IST_OFFSET)).date()\n\n\n@dataclass\nclass Trade:\n    date: str\n    tradingsymbol: str\n    side: str\n    kind: str\n    strike: float\n    expiry: str\n    dte: int\n    entry_ts: int\n    entry_time: str\n    entry_price: float\n    entry_spot: float\n    sl_spot: float\n    tp_spot: float\n    risk_pts: float\n    exit_ts: int = 0\n    exit_time: str = ""\n    exit_price: float = 0.0\n    exit_reason: str = ""\n    qty: int = 0\n    hold_min: int = 0\n    gross: float = 0.0\n    charges: float = 0.0\n    net: float = 0.0\n    net_alt_fill: float = 0.0          # net if the SL had filled at option CLOSE\n    mae: float = 0.0\n    mfe: float = 0.0\n    r_mult: float = 0.0                # spot-based R at exit (diagnostic)\n    fallback_strike: int = 0\n    stale_marks: int = 0\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  CORPUS\n# ─────────────────────────────────────────────────────────────────────────\nclass Corpus:\n    def __init__(self, db_path: str, underlying: str):\n        self.path = db_path\n        self.u = underlying\n        self.c = sqlite3.connect(db_path)\n        self.c.row_factory = sqlite3.Row\n        for p in ("PRAGMA cache_size=-131072;", "PRAGMA temp_store=MEMORY;",\n                  "PRAGMA mmap_size=536870912;", "PRAGMA query_only=1;"):\n            try:\n                self.c.execute(p)\n            except sqlite3.DatabaseError:\n                pass\n        self.spot: Dict[date, List[Bar]] = {}\n        self.expiry_ranges: List[Tuple[str, int, int]] = []\n        self._opt_cache: Dict[Tuple[str, int], Dict[int, Bar]] = {}\n        self._cache_order: List[Tuple[str, int]] = []\n\n    def load_spot(self, d_from: date, d_to: date) -> None:\n        t0 = time.time()\n        ts_from, ts_to = day_start_epoch(d_from), day_start_epoch(d_to) + 86400\n        rows = self.c.execute(\n            "SELECT ts, open, high, low, close FROM backtest_candles_1m "\n            "WHERE tradingsymbol=? AND ts>=? AND ts<? ORDER BY ts",\n            (SPOT_SYMBOL.get(self.u, f"{self.u}SPOT"), ts_from, ts_to)).fetchall()\n        if not rows:\n            rows = self.c.execute(\n                "SELECT ts, open, high, low, close FROM backtest_candles_1m "\n                "WHERE underlying=? AND expiry=\'\' AND instrument_type=\'SPOT\' "\n                "AND ts>=? AND ts<? ORDER BY ts", (self.u, ts_from, ts_to)).fetchall()\n        for r in rows:\n            d = epoch_day(r["ts"])\n            self.spot.setdefault(d, []).append(Bar(r["ts"], r["open"], r["high"], r["low"], r["close"]))\n        print(f"[corpus] spot bars {len(rows):,} across {len(self.spot)} sessions "\n              f"({time.time() - t0:.1f}s)")\n\n    def load_expiry_ranges(self) -> None:\n        t0 = time.time()\n        rows = self.c.execute(\n            "SELECT expiry, MIN(ts) AS a, MAX(ts) AS b FROM backtest_candles_1m "\n            "WHERE underlying=? AND expiry<>\'\' GROUP BY expiry ORDER BY expiry", (self.u,)).fetchall()\n        self.expiry_ranges = [(r["expiry"], int(r["a"]), int(r["b"])) for r in rows]\n        print(f"[corpus] {len(self.expiry_ranges)} option expiries with prints "\n              f"({time.time() - t0:.1f}s)")\n\n    def front_expiry(self, d: date) -> Optional[str]:\n        ds, de = day_start_epoch(d), day_start_epoch(d) + 86400\n        iso = d.isoformat()\n        for exp, a, b in self.expiry_ranges:\n            if exp >= iso and a < de and b >= ds:\n                return exp\n        return None\n\n    def chain_at(self, expiry: str, ts: int, side: str) -> List[dict]:\n        rows = self.c.execute(\n            "SELECT tradingsymbol, strike FROM backtest_candles_1m "\n            "WHERE underlying=? AND expiry=? AND ts=? AND instrument_type=? AND open>0",\n            (self.u, expiry, ts, side)).fetchall()\n        return [{"tradingsymbol": r["tradingsymbol"], "strike": float(r["strike"])} for r in rows]\n\n    def option_day(self, sym: str, ds: int) -> Dict[int, Bar]:\n        key = (sym, ds)\n        hit = self._opt_cache.get(key)\n        if hit is not None:\n            return hit\n        rows = self.c.execute(\n            "SELECT ts, open, high, low, close FROM backtest_candles_1m "\n            "WHERE tradingsymbol=? AND ts>=? AND ts<? ORDER BY ts", (sym, ds, ds + 86400)).fetchall()\n        out = {int(r["ts"]): Bar(r["ts"], r["open"], r["high"], r["low"], r["close"]) for r in rows}\n        self._opt_cache[key] = out\n        self._cache_order.append(key)\n        if len(self._cache_order) > 4000:\n            old = self._cache_order.pop(0)\n            self._opt_cache.pop(old, None)\n        return out\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  CONFIG\n# ─────────────────────────────────────────────────────────────────────────\ndef merge_cfg(over: Optional[dict]) -> dict:\n    cfg = dict(DEFAULTS)\n    for k, v in (over or {}).items():\n        if k not in DEFAULTS:\n            raise SystemExit(f"unknown config key: {k}")\n        base = DEFAULTS[k]\n        if isinstance(base, bool) or isinstance(base, int):\n            cfg[k] = int(float(v))\n        elif isinstance(base, float):\n            cfg[k] = float(v)\n        else:\n            cfg[k] = str(v)\n    cfg["direction"] = cfg["direction"].upper()\n    if cfg["direction"] not in ("BOTH", "CE", "PE"):\n        raise SystemExit("direction must be BOTH | CE | PE")\n    cfg["sl_fill"] = "close" if cfg["sl_fill"].lower() == "close" else "low"\n    cfg["sl_trigger"] = "close" if cfg["sl_trigger"].lower() == "close" else "touch"\n    if cfg["dte_min"] > cfg["dte_max"]:\n        raise SystemExit("dte_min must be <= dte_max")\n    cfg["tp_mode"] = "fib" if cfg["tp_mode"].lower() == "fib" else "rr"\n    cfg["entry_mode"] = cfg["entry_mode"].lower()\n    if cfg["entry_mode"] not in ("fvg", "fixed", "matched"):\n        raise SystemExit("entry_mode must be fvg | fixed | matched")\n    if cfg["fixed_sl_pts"] <= 0:\n        raise SystemExit("fixed_sl_pts must be > 0")\n    if not (1 <= cfg["tf"] <= 30):\n        raise SystemExit("tf must be 1..30")\n    if cfg["tp_rr"] <= 0:\n        raise SystemExit("tp_rr must be > 0")\n    if not (SESSION_OPEN_MIN <= _hhmm(cfg["entry_from"]) < _hhmm(cfg["entry_until"])\n            <= _hhmm(cfg["eod_square_off"]) <= 15 * 60 + 29):\n        raise SystemExit("time order must be 09:15 <= entry_from < entry_until <= eod <= 15:29")\n    return cfg\n\n\ndef engine_cfg(cfg: dict) -> EngineConfig:\n    return EngineConfig(atr_len=cfg["atr_len"], disp_atr=cfg["disp_atr"],\n                        gap_min_atr=cfg["gap_min_atr"], fib_gate=bool(cfg["fib_gate"]),\n                        fib_lo=cfg["fib_lo"], fib_hi=cfg["fib_hi"],\n                        fib_lookback=cfg["fib_lookback"], sl_buf_atr=cfg["sl_buf_atr"],\n                        gap_max_age=cfg["gap_max_age"], trade_fvg=bool(cfg["trade_fvg"]),\n                        trade_ifvg=bool(cfg["trade_ifvg"]), direction=cfg["direction"],\n                        max_gaps=cfg["max_gaps"])\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  RUN\n# ─────────────────────────────────────────────────────────────────────────\ndef run(corpus: Corpus, cfg: dict, d_from: date, d_to: date, **_ignored) -> dict:\n    lot = INDEX_LOTS[corpus.u]\n    qty = cfg["lots"] * lot\n    tf = cfg["tf"]\n    e_from, e_until, eod_min = _hhmm(cfg["entry_from"]), _hhmm(cfg["entry_until"]), _hhmm(cfg["eod_square_off"])\n    sessions = sorted(corpus.spot)\n    idx_from = next((i for i, d in enumerate(sessions) if d >= d_from), len(sessions))\n    warm = sessions[max(0, idx_from - cfg["warmup_sessions"]):idx_from]\n    days = [d for d in sessions[idx_from:] if d <= d_to]\n    session_index = {d: i for i, d in enumerate(sessions)}\n\n    atr = ATR(cfg["atr_len"])\n    eng = FvgEngine(engine_cfg(cfg), atr)\n    for wd in warm:\n        session_signals(eng, corpus.spot[wd], day_start_epoch=day_start_epoch(wd), tf_minutes=tf)\n\n    diag: Dict[str, float] = {k: 0 for k in (\n        "days_total", "days_traded", "days_uncovered", "days_thin", "days_skipped_expiry", "days_skipped_dte",\n        "signals_total", "sig_dropped_open", "sig_dropped_budget", "sig_dropped_window",\n        "sig_dropped_daily_loss", "sig_no_spot_bar", "sig_bad_risk", "sig_risk_too_wide",\n        "sig_sl_widened", "sig_no_candidate", "sig_no_fill", "sig_band_reject",\n        "strike_fallbacks", "tp_fib_fallback", "entries", "ce_entries", "pe_entries",\n        "fvg_entries", "ifvg_entries", "sl_exits", "tp_exits", "time_exits", "eod_exits",\n        "be_exits", "sl_in_entry_minute", "stale_marks", "be_armed")}\n    trades: List[Trade] = []\n    day_r_sum = 0.0\n\n    for d in days:\n        diag["days_total"] += 1\n        bars_1m = corpus.spot[d]\n        ds = day_start_epoch(d)\n        if len(bars_1m) < 300:\n            diag["days_thin"] += 1\n        sigs = session_signals(eng, bars_1m, day_start_epoch=ds, tf_minutes=tf)   # ATR always advances\n        if not sigs and cfg["entry_mode"] != "fixed":\n            continue\n        exp = corpus.front_expiry(d)\n        if exp is None:\n            diag["days_uncovered"] += 1\n            continue\n        exp_d = date.fromisoformat(exp)\n        dte = 0\n        if exp_d in session_index:\n            dte = max(0, session_index[exp_d] - session_index[d])\n        else:                               # expiry beyond the loaded window: weekday count\n            dte = sum(1 for i in range(1, (exp_d - d).days + 1)\n                      if (d + timedelta(days=i)).weekday() < 5)\n        if dte > cfg["max_dte_sessions"]:\n            diag["days_uncovered"] += 1\n            continue\n        if cfg["skip_expiry_day"] and dte == 0:\n            diag["days_skipped_expiry"] += 1\n            continue\n        if not (cfg["dte_min"] <= dte <= cfg["dte_max"]):\n            diag["days_skipped_dte"] += 1\n            continue\n        by_min = {(b.ts - ds) // 60: b for b in bars_1m}\n        if cfg["entry_mode"] != "fvg":\n            # ── CONTROL (round 5) ── replace the day\'s signals with ONE fixed-\n            # time entry. "matched" keeps only days where the strategy itself\n            # would have had a tradeable signal in the window.\n            side = "PE" if cfg["direction"] == "PE" else "CE"\n            if cfg["entry_mode"] == "matched" and not any(\n                    x.side == side and e_from <= x.trigger_min + 1 < e_until for x in sigs):\n                continue\n            fmin = _hhmm(cfg["fixed_entry_time"])\n            sb0 = by_min.get(fmin)\n            if sb0 is None:\n                diag["sig_no_spot_bar"] += 1\n                continue\n            lvl = (float(sb0.open) - cfg["fixed_sl_pts"] if side == "CE"\n                   else float(sb0.open) + cfg["fixed_sl_pts"])\n            sigs = [Signal(trigger_min=fmin - 1, side=side, kind="CTRL", sl_level=lvl,\n                           zone_top=0.0, zone_bottom=0.0, leg_target=None,\n                           atr=float(eng.atr.value or cfg["fixed_sl_pts"]), gid=0)]\n        diag["signals_total"] += len(sigs)\n        open_until = -1\n        day_trades = 0\n        day_r_sum = 0.0\n        traded = False\n        step_cache: Optional[float] = None\n\n        for s in sigs:\n            entry_min = s.trigger_min + 1\n            if entry_min <= open_until:\n                diag["sig_dropped_open"] += 1\n                continue\n            if cfg["max_trades_per_day"] and day_trades >= cfg["max_trades_per_day"]:\n                diag["sig_dropped_budget"] += 1\n                continue\n            if not (e_from <= entry_min < e_until):\n                diag["sig_dropped_window"] += 1\n                continue\n            if cfg["daily_loss_r"] > 0 and day_r_sum <= -cfg["daily_loss_r"]:\n                diag["sig_dropped_daily_loss"] += 1\n                continue\n            sb = by_min.get(entry_min)\n            if sb is None:\n                diag["sig_no_spot_bar"] += 1\n                continue\n            entry_spot = float(sb.open)\n            bull = s.side == "CE"\n            sl = s.sl_level\n            risk = (entry_spot - sl) if bull else (sl - entry_spot)\n            if risk <= 0:\n                diag["sig_bad_risk"] += 1\n                continue\n            if risk < cfg["sl_min_pts"]:\n                risk = cfg["sl_min_pts"]\n                sl = entry_spot - risk if bull else entry_spot + risk\n                diag["sig_sl_widened"] += 1\n            if cfg["sl_max_atr"] > 0 and risk > cfg["sl_max_atr"] * s.atr:\n                diag["sig_risk_too_wide"] += 1\n                continue\n            tp = entry_spot + cfg["tp_rr"] * risk if bull else entry_spot - cfg["tp_rr"] * risk\n            if cfg["tp_mode"] == "fib":\n                lt = s.leg_target\n                ok = lt is not None and ((lt - entry_spot) if bull else (entry_spot - lt)) >= cfg["tp_fib_min_rr"] * risk\n                if ok:\n                    tp = float(lt)\n                else:\n                    diag["tp_fib_fallback"] += 1\n            fill_ts = ds + entry_min * 60\n            chain = corpus.chain_at(exp, fill_ts, s.side)\n            if not chain:\n                diag["sig_no_candidate"] += 1\n                continue\n            if step_cache is None:\n                step_cache = strike_step([c["strike"] for c in chain])\n            sign = 1 if bull else -1\n            target_strike = atm_strike(entry_spot, step_cache) + sign * cfg["strike_offset"] * step_cache\n            mc = min(chain, key=lambda c: (abs(c["strike"] - target_strike), c["strike"]))\n            fallback = int(mc["strike"] != target_strike)\n            diag["strike_fallbacks"] += fallback\n            ob = corpus.option_day(mc["tradingsymbol"], ds)\n            fb = ob.get(fill_ts)\n            if fb is None or not fb.open:\n                diag["sig_no_fill"] += 1\n                continue\n            entry_px = float(fb.open)\n            if (cfg["premium_max"] > 0 and entry_px >= cfg["premium_max"]) or \\\n               (cfg["premium_min"] > 0 and entry_px < cfg["premium_min"]):\n                diag["sig_band_reject"] += 1\n                continue\n\n            t = Trade(date=d.isoformat(), tradingsymbol=mc["tradingsymbol"], side=s.side,\n                      kind=s.kind, strike=mc["strike"], expiry=exp, dte=dte,\n                      entry_ts=fill_ts, entry_time=f"{entry_min // 60:02d}:{entry_min % 60:02d}",\n                      entry_price=round(entry_px, 2), entry_spot=round(entry_spot, 2),\n                      sl_spot=round(sl, 2), tp_spot=round(tp, 2), risk_pts=round(risk, 2),\n                      qty=qty, fallback_strike=fallback)\n            diag["entries"] += 1\n            diag["ce_entries" if bull else "pe_entries"] += 1\n            if s.kind == "FVG":\n                diag["fvg_entries"] += 1\n            elif s.kind == "IFVG":\n                diag["ifvg_entries"] += 1\n            day_trades += 1\n            traded = True\n\n            last_mark = entry_px\n            mae = mfe = 0.0\n            cur_sl, be_armed = sl, False\n            exit_min = eod_min\n            exit_px = alt_px = None\n            reason = None\n            for m in range(entry_min, eod_min + 1):\n                o = ob.get(ds + m * 60)\n                if o is not None:\n                    last_mark = float(o.close)\n                    mae = min(mae, float(o.low) - entry_px)\n                    mfe = max(mfe, float(o.high) - entry_px)\n                else:\n                    t.stale_marks += 1\n                if m >= eod_min:\n                    exit_px = alt_px = last_mark\n                    reason, exit_min = "EOD", m\n                    break\n                b = by_min.get(m)\n                if b is not None:\n                    if cfg["sl_trigger"] == "close":      # wick-immune (ORB_SLTRIG convention)\n                        sl_hit = (b.close <= cur_sl) if bull else (b.close >= cur_sl)\n                        tp_hit = (b.close >= tp) if bull else (b.close <= tp)\n                    else:\n                        sl_hit = (b.low <= cur_sl) if bull else (b.high >= cur_sl)\n                        tp_hit = (b.high >= tp) if bull else (b.low <= tp)\n                    if sl_hit or tp_hit:\n                        reason = ("BE" if be_armed else "SL") if sl_hit else "TP"\n                        if cfg["sl_trigger"] == "close":\n                            # both fill at the NEXT minute\'s option open; the\n                            # artifact reference is this minute\'s close\n                            m2 = min(m + 1, eod_min)\n                            o2 = ob.get(ds + m2 * 60)\n                            exit_px = float(o2.open) if (o2 is not None and o2.open) else last_mark\n                            alt_px = last_mark\n                            exit_min = m2\n                        elif sl_hit:\n                            if o is None:\n                                exit_px = alt_px = last_mark\n                            else:\n                                exit_px = float(o.close) if cfg["sl_fill"] == "close" else float(o.low)\n                                alt_px = float(o.close) if cfg["sl_fill"] == "low" else float(o.low)\n                            exit_min = m\n                        else:\n                            exit_px = alt_px = last_mark\n                            exit_min = m\n                        if sl_hit and m == entry_min:\n                            diag["sl_in_entry_minute"] += 1\n                        break\n                    if cfg["be_rr"] > 0 and not be_armed:\n                        fav = (b.high - entry_spot) if bull else (entry_spot - b.low)\n                        if fav >= cfg["be_rr"] * risk:\n                            be_armed, cur_sl = True, entry_spot\n                            diag["be_armed"] += 1\n                if m - entry_min + 1 >= cfg["hold_max"]:\n                    exit_px = alt_px = last_mark\n                    reason, exit_min = "TIME", m\n                    break\n            if exit_px is None:\n                exit_px = alt_px = last_mark\n                reason, exit_min = "EOD", eod_min\n            gross = (exit_px - entry_px) * qty\n            ch = charges_long(entry_px, exit_px, qty)\n            t.exit_ts = ds + exit_min * 60\n            t.exit_time = f"{exit_min // 60:02d}:{exit_min % 60:02d}"\n            t.exit_price, t.exit_reason = round(exit_px, 2), reason\n            t.hold_min = exit_min - entry_min + 1\n            t.gross, t.charges, t.net = round(gross, 2), ch, round(gross - ch, 2)\n            t.net_alt_fill = round((alt_px - entry_px) * qty - charges_long(entry_px, alt_px, qty), 2)\n            t.mae, t.mfe = round(mae * qty, 2), round(mfe * qty, 2)\n            xs = by_min.get(exit_min)\n            if xs is not None and risk > 0:\n                sp = float(xs.close)\n                t.r_mult = round(((sp - entry_spot) if bull else (entry_spot - sp)) / risk, 2)\n            diag[f"{reason.lower()}_exits"] += 1\n            diag["stale_marks"] += t.stale_marks\n            trades.append(t)\n            day_r_sum += t.r_mult\n            open_until = exit_min\n        if traded:\n            diag["days_traded"] += 1\n    eng_diag = dict(eng.diag)\n    return {"cfg": cfg, "trades": trades, "diag": diag, "engine_diag": eng_diag,\n            "score": scoreboard(trades)}\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  SCOREBOARD — Anbu\'s priority order:\n#  yearly signs → worst month → consecutive losing months → positive months → DD → net\n# ─────────────────────────────────────────────────────────────────────────\ndef scoreboard(trades: List[Trade]) -> dict:\n    if not trades:\n        return {"trades": 0, "net": 0.0, "years": {}, "months": {}, "pos_years": 0, "n_years": 0,\n                "worst_month": 0.0, "max_consec_losing_months": 0, "pos_months": 0, "n_months": 0,\n                "max_dd": 0.0, "win_rate": 0.0, "avg_win": 0.0, "avg_loss": 0.0, "pf": 0.0,\n                "net_alt_fill": 0.0, "charges": 0.0, "gross": 0.0, "net_a": 0.0, "net_b": 0.0}\n    years: Dict[str, float] = {}\n    months: Dict[str, float] = {}\n    eq = peak = mdd = 0.0\n    for t in sorted(trades, key=lambda x: (x.exit_ts, x.entry_ts)):\n        years[t.date[:4]] = years.get(t.date[:4], 0.0) + t.net\n        months[t.date[:7]] = months.get(t.date[:7], 0.0) + t.net\n        eq += t.net\n        peak = max(peak, eq)\n        mdd = max(mdd, peak - eq)\n    consec = worst_consec = 0\n    for ym in sorted(months):\n        consec = consec + 1 if months[ym] < 0 else 0\n        worst_consec = max(worst_consec, consec)\n    nets = [t.net for t in trades]\n    wins = [n for n in nets if n > 0]\n    losses = [n for n in nets if n <= 0]\n    gp, gl = sum(wins), -sum(losses)\n    return {\n        "trades": len(trades), "net": round(sum(nets), 2),\n        "gross": round(sum(t.gross for t in trades), 2),\n        "charges": round(sum(t.charges for t in trades), 2),\n        "net_alt_fill": round(sum(t.net_alt_fill for t in trades), 2),\n        "years": {y: round(v, 2) for y, v in sorted(years.items())},\n        "net_a": round(sum(v for y, v in years.items() if y < SPLIT_YEAR), 2),\n        "net_b": round(sum(v for y, v in years.items() if y >= SPLIT_YEAR), 2),\n        "months": {m: round(v, 2) for m, v in sorted(months.items())},\n        "pos_years": sum(1 for v in years.values() if v > 0), "n_years": len(years),\n        "worst_month": round(min(months.values()), 2),\n        "max_consec_losing_months": worst_consec,\n        "pos_months": sum(1 for v in months.values() if v > 0), "n_months": len(months),\n        "max_dd": round(mdd, 2),\n        "win_rate": round(100.0 * len(wins) / len(nets), 1),\n        "avg_win": round(gp / len(wins), 0) if wins else 0.0,\n        "avg_loss": round(-gl / len(losses), 0) if losses else 0.0,\n        "pf": round(gp / gl, 2) if gl > 0 else float("inf"),\n    }\n\n\ndef rank_key(sc: dict):\n    """Sort key for sweeps: higher = better on every axis."""\n    n_years = max(sc["n_years"], 1)\n    return (sc["pos_years"] / n_years, sc["worst_month"], -sc["max_consec_losing_months"],\n            sc["pos_months"] / max(sc["n_months"], 1), -sc["max_dd"], sc["net"])\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  REPORT\n# ─────────────────────────────────────────────────────────────────────────\ndef _lakh(v: float) -> str:\n    return f"₹{v / 1e5:,.2f}L" if abs(v) >= 1e5 else f"₹{v:,.0f}"\n\n\ndef _share(part: float, net: float) -> str:\n    return f"{100.0 * part / net:5.0f}%" if abs(net) > 1e-9 else "   n/a"\n\n\ndef report(res: dict, *, months: bool = False) -> None:\n    sc, dg, ed, tr, cfg = res["score"], res["diag"], res["engine_diag"], res["trades"], res["cfg"]\n    print("=" * 78)\n    if cfg["entry_mode"] != "fvg":\n        print(f"CONTROL [{cfg[\'entry_mode\']}]  fixed entry {cfg[\'fixed_entry_time\']}  "\n              f"stop {cfg[\'fixed_sl_pts\']} pts  (no setup)")\n    print(f"FVG_V1 lab  {cfg[\'direction\']}  tf={cfg[\'tf\']}m  disp={cfg[\'disp_atr\']}ATR  "\n          f"gap>={cfg[\'gap_min_atr\']}ATR  fib={\'on\' if cfg[\'fib_gate\'] else \'off\'} "\n          f"[{cfg[\'fib_lo\']}-{cfg[\'fib_hi\']}]  FVG={cfg[\'trade_fvg\']} IFVG={cfg[\'trade_ifvg\']}")\n    print(f"  stop: structural, min {cfg[\'sl_min_pts\']}pt, max {cfg[\'sl_max_atr\']}ATR, buf "\n          f"{cfg[\'sl_buf_atr\']}ATR, trigger={cfg[\'sl_trigger\']}, fill={cfg[\'sl_fill\']} | tp: {cfg[\'tp_mode\']} "\n          f"rr={cfg[\'tp_rr\']} | be_rr={cfg[\'be_rr\']} | hold<={cfg[\'hold_max\']}m | "\n          f"window {cfg[\'entry_from\']}-{cfg[\'entry_until\']} eod {cfg[\'eod_square_off\']} | "\n          f"max/day {cfg[\'max_trades_per_day\']} | dte {cfg[\'dte_min\']}-{cfg[\'dte_max\']} | lots {cfg[\'lots\']}")\n    print("-" * 78)\n    if not tr:\n        print("NO TRADES.  engine:", ed, "\\n  runner:", {k: v for k, v in dg.items() if v})\n        return\n    print(f"SCOREBOARD  years +{sc[\'pos_years\']}/{sc[\'n_years\']}  worst month {_lakh(sc[\'worst_month\'])}  "\n          f"consec losing months {sc[\'max_consec_losing_months\']}  months +{sc[\'pos_months\']}/{sc[\'n_months\']}  "\n          f"maxDD {_lakh(sc[\'max_dd\'])}  net {_lakh(sc[\'net\'])}")\n    ndd = sc["net"] / sc["max_dd"] if sc["max_dd"] > 0 else float("inf")\n    print(f"  trades {sc[\'trades\']}  win {sc[\'win_rate\']}%  avg win {sc[\'avg_win\']:,.0f}  "\n          f"avg loss {sc[\'avg_loss\']:,.0f}  PF {sc[\'pf\']}  net/DD {ndd:.2f}  "\n          f"gross {_lakh(sc[\'gross\'])}  charges {_lakh(sc[\'charges\'])}")\n    print("  years: " + "  ".join(f"{y} {_lakh(v)}" for y, v in sc["years"].items())\n          + f"   | split: <{SPLIT_YEAR} {_lakh(sc[\'net_a\'])}  >={SPLIT_YEAR} {_lakh(sc[\'net_b\'])}")\n    if months:\n        ms = sc["months"]\n        print("  months:")\n        for y in sorted({m[:4] for m in ms}):\n            row = [f"{ms.get(f\'{y}-{mm:02d}\', 0) / 1000:+7.1f}k" if f"{y}-{mm:02d}" in ms else "      ."\n                   for mm in range(1, 13)]\n            print(f"    {y} " + " ".join(row))\n    net = sc["net"]\n    by_reason: Dict[str, List[float]] = {}\n    by_kind: Dict[str, List[float]] = {}\n    by_side: Dict[str, List[float]] = {}\n    by_hour: Dict[str, List[float]] = {}\n    by_dte: Dict[int, List[float]] = {}\n    for t in tr:\n        by_reason.setdefault(t.exit_reason, []).append(t.net)\n        by_kind.setdefault(t.kind, []).append(t.net)\n        by_side.setdefault(t.side, []).append(t.net)\n        by_hour.setdefault(t.entry_time[:2], []).append(t.net)\n        by_dte.setdefault(t.dte, []).append(t.net)\n\n    def line(title: str, d: dict) -> None:\n        parts = []\n        for k in sorted(d, key=lambda x: str(x)):\n            v = d[k]\n            parts.append(f"{k}: n={len(v)} net={_lakh(sum(v))} ({_share(sum(v), net).strip()})")\n        print(f"  {title}: " + " | ".join(parts))\n\n    print("FALSIFICATION")\n    line("exits", by_reason)\n    line("setup", by_kind)\n    line("side", by_side)\n    line("entry hour", by_hour)\n    line("DTE", by_dte)\n    top = sorted((t.net for t in tr), reverse=True)[:5]\n    top_sum = sum(x for x in top if x > 0)\n    per_year_n = {}\n    for t in tr:\n        per_year_n[t.date[:4]] = per_year_n.get(t.date[:4], 0) + 1\n    print(f"  concentration: top-5 winners {_lakh(top_sum)} = {_share(top_sum, net).strip()} of net; "\n          f"net without them {_lakh(net - top_sum)}; trades/year "\n          + " ".join(f"{y}:{n}" for y, n in sorted(per_year_n.items())))\n    print(f"  SL-fill artifact: net(low fill) {_lakh(sc[\'net\'])} vs net(close fill) "\n          f"{_lakh(sc[\'net_alt_fill\'])}  → convention worth {_lakh(sc[\'net_alt_fill\'] - sc[\'net\'])}")\n    sl_n = dg["sl_exits"] + dg["be_exits"]\n    print(f"  stops in entry minute: {int(dg[\'sl_in_entry_minute\'])}/{int(sl_n)} "\n          f"({100.0 * dg[\'sl_in_entry_minute\'] / sl_n if sl_n else 0:.0f}%)  "\n          f"avg risk {sum(t.risk_pts for t in tr) / len(tr):.1f} pts  "\n          f"avg hold {sum(t.hold_min for t in tr) / len(tr):.0f} min  "\n          f"avg premium {sum(t.entry_price for t in tr) / len(tr):.0f}")\n    print(f"  signals {int(dg[\'signals_total\'])} → entries {int(dg[\'entries\'])}; dropped: open "\n          f"{int(dg[\'sig_dropped_open\'])}, window {int(dg[\'sig_dropped_window\'])}, budget "\n          f"{int(dg[\'sig_dropped_budget\'])}, daily-loss {int(dg[\'sig_dropped_daily_loss\'])}, "\n          f"bad-risk {int(dg[\'sig_bad_risk\'])}, too-wide {int(dg[\'sig_risk_too_wide\'])}, "\n          f"no-candidate {int(dg[\'sig_no_candidate\'])}, no-fill {int(dg[\'sig_no_fill\'])}, "\n          f"band {int(dg[\'sig_band_reject\'])}; sl widened {int(dg[\'sig_sl_widened\'])}, "\n          f"strike fallbacks {int(dg[\'strike_fallbacks\'])}, stale marks {int(dg[\'stale_marks\'])}")\n    print(f"  days: total {int(dg[\'days_total\'])}, traded {int(dg[\'days_traded\'])}, uncovered "\n          f"{int(dg[\'days_uncovered\'])}, thin {int(dg[\'days_thin\'])}, skipped-expiry "\n          f"{int(dg[\'days_skipped_expiry\'])}, skipped-dte {int(dg[\'days_skipped_dte\'])}")\n    print(f"  engine: gaps raw {ed.get(\'gap_raw\', 0)}, rejected displacement "\n          f"{ed.get(\'gap_rej_displacement\', 0)}, width {ed.get(\'gap_rej_width\', 0)}; born "\n          f"bull {ed.get(\'gap_born_bull\', 0)} / bear {ed.get(\'gap_born_bear\', 0)}; fib ok "\n          f"{ed.get(\'gap_fib_ok\', 0)} / reject {ed.get(\'gap_fib_reject\', 0)}; inverted "\n          f"{ed.get(\'gap_inverted\', 0)}; expired {ed.get(\'gap_expired\', 0)}; triggers FVG "\n          f"{ed.get(\'trig_fvg\', 0)} / IFVG {ed.get(\'trig_ifvg\', 0)}")\n\n\ndef export_csv(trades: List[Trade], path: str) -> None:\n    if not trades:\n        print("nothing to export")\n        return\n    with open(path, "w", newline="") as f:\n        w = csv.DictWriter(f, fieldnames=list(asdict(trades[0]).keys()))\n        w.writeheader()\n        for t in trades:\n            w.writerow(asdict(t))\n    print(f"[export] {len(trades)} trades → {path}")\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  CLI\n# ─────────────────────────────────────────────────────────────────────────\ndef parse_sets(items: List[str]) -> dict:\n    out = {}\n    for it in items or []:\n        if "=" not in it:\n            raise SystemExit(f"--set expects key=value, got {it}")\n        k, v = it.split("=", 1)\n        out[k.strip()] = v.strip()\n    return out\n\n\ndef parse_grid(spec: str) -> List[dict]:\n    axes = []\n    for part in spec.split(";"):\n        part = part.strip()\n        if not part:\n            continue\n        k, vs = part.split("=", 1)\n        axes.append((k.strip(), [v.strip() for v in vs.split(",") if v.strip()]))\n    combos = []\n    for vals in itertools.product(*[v for _, v in axes]):\n        combos.append({k: v for (k, _), v in zip(axes, vals)})\n    return combos\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(description="FVG/IFVG + Fibonacci NIFTY option-buying lab backtest")\n    ap.add_argument("--db", default=str(Path.home() / ".scalp-app" / "backtest" / "backtest.db"))\n    ap.add_argument("--underlying", default="NIFTY")\n    ap.add_argument("--from", dest="d_from", default="2020-01-01")\n    ap.add_argument("--to", dest="d_to", default=date.today().isoformat())\n    ap.add_argument("--lots", type=int, default=None)\n    ap.add_argument("--set", nargs="*", default=[], help="key=value overrides (see DEFAULTS)")\n    ap.add_argument("--grid", default=None, help=\'sweep, e.g. "tf=3,5;tp_rr=1.5,2,3"\')\n    ap.add_argument("--top", type=int, default=15, help="rows to show for --grid")\n    ap.add_argument("--months", action="store_true", help="print the monthly table")\n    ap.add_argument("--export", default=None, help="CSV path for the trades of the (single) run")\n    ap.add_argument("--defaults", action="store_true", help="print DEFAULTS and exit")\n    a = ap.parse_args()\n    if a.defaults:\n        for k, v in DEFAULTS.items():\n            print(f"  {k:20s} {v}")\n        return\n    if not os.path.exists(a.db):\n        raise SystemExit(f"corpus not found: {a.db}")\n    over = parse_sets(a.set)\n    if a.lots is not None:\n        over["lots"] = a.lots\n    d_from, d_to = date.fromisoformat(a.d_from), date.fromisoformat(a.d_to)\n    corpus = Corpus(a.db, a.underlying.upper())\n    corpus.load_spot(d_from - timedelta(days=30), d_to)\n    corpus.load_expiry_ranges()\n    if not corpus.spot:\n        raise SystemExit("no SPOT rows in the corpus for that window")\n\n    if a.grid:\n        combos = parse_grid(a.grid)\n        rows = []\n        t0 = time.time()\n        for i, c in enumerate(combos):\n            cfg = merge_cfg({**over, **c})\n            res = run(corpus, cfg, d_from, d_to, quiet=True)\n            sc = res["score"]\n            rows.append((rank_key(sc), c, sc, res["diag"]))\n            print(f"  [{i + 1}/{len(combos)}] {c} → trades {sc[\'trades\']} net {_lakh(sc[\'net\'])} "\n                  f"DD {_lakh(sc[\'max_dd\'])} years +{sc[\'pos_years\']}/{sc[\'n_years\']} "\n                  f"({time.time() - t0:.0f}s)", flush=True)\n        rows.sort(key=lambda r: r[0], reverse=True)\n        print("\\nRANKED (yearly signs → worst month → consec losing → +months → DD → net)")\n        print(f"{\'#\':>3} {\'config\':45s} {\'trades\':>6} {\'yrs\':>5} {\'worstM\':>9} {\'consec\':>6} "\n              f"{\'+M\':>7} {\'maxDD\':>10} {\'net\':>10} {\'net/DD\':>7} {\'SLfill\':>10} "\n              f"{\'<\' + SPLIT_YEAR:>9} {\'>=\' + SPLIT_YEAR:>9}")\n        for i, (_, c, sc, dg) in enumerate(rows[:a.top]):\n            ndd = sc["net"] / sc["max_dd"] if sc["max_dd"] > 0 else 0.0\n            cs = ",".join(f"{k}={v}" for k, v in c.items())\n            print(f"{i + 1:3d} {cs[:45]:45s} {sc[\'trades\']:6d} {sc[\'pos_years\']:>2}/{sc[\'n_years\']:<2} "\n                  f"{sc[\'worst_month\'] / 1000:8.1f}k {sc[\'max_consec_losing_months\']:6d} "\n                  f"{sc[\'pos_months\']:>3}/{sc[\'n_months\']:<3} {sc[\'max_dd\'] / 1000:9.1f}k "\n                  f"{sc[\'net\'] / 1000:9.1f}k {ndd:7.2f} {(sc[\'net_alt_fill\'] - sc[\'net\']) / 1000:9.1f}k "\n                  f"{sc[\'net_a\'] / 1000:8.1f}k {sc[\'net_b\'] / 1000:8.1f}k")\n        return\n\n    cfg = merge_cfg(over)\n    t0 = time.time()\n    res = run(corpus, cfg, d_from, d_to)\n    report(res, months=a.months)\n    print(f"  ({time.time() - t0:.1f}s)")\n    if a.export:\n        export_csv(res["trades"], a.export)\n\n\nif __name__ == "__main__":\n    main()\n', 'tools/lab/fvg/test_fvg_fib.py': '#!/usr/bin/env python3\n# test_fvg_fib.py — FVG_LAB_20260916 behavioural suite.\n#\n#   python3 test_fvg_fib.py\n#\n# Part A: engine scenarios on hand-built bars (gap birth, fib gate, touch →\n#         rejection trigger, inversion → IFVG trigger, expiry, direction gate).\n# Part B: end-to-end run on a SYNTHETIC backtest.db with the real\n#         backtest_candles_1m schema (SPOT rows + BS-priced weekly options),\n#         then the CLI (single run, --months, --export, --grid).\n# Nothing here touches ~/.scalp-app.\n\nfrom __future__ import annotations\n\nimport math\nimport os\nimport random\nimport sqlite3\nimport subprocess\nimport sys\nimport tempfile\nfrom datetime import date, datetime, timedelta\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\nfrom fvg_fib_engine import (Bar, ATR, EngineConfig, FvgEngine, resample_session,   # noqa: E402\n                            session_signals, SESSION_OPEN_MIN, IST_OFFSET)\nimport fvg_fib_backtest as bt   # noqa: E402\n\nFAILS = 0\n\n\ndef check(cond: bool, msg: str) -> None:\n    global FAILS\n    print(("  ok   " if cond else "  FAIL ") + msg)\n    if not cond:\n        FAILS += 1\n\n\ndef ds_of(d: date) -> int:\n    return int((datetime(d.year, d.month, d.day) - datetime(1970, 1, 1)).total_seconds()) - IST_OFFSET\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  PART A — engine scenarios\n# ─────────────────────────────────────────────────────────────────────────\ndef flat_minutes(ds: int, start_min: int, n: int, px: float, rng: float = 2.0):\n    """n quiet 1m bars around px."""\n    return [Bar(ds + (start_min + i) * 60, px, px + rng, px - rng, px) for i in range(n)]\n\n\ndef m1(ds: int, mod: int, o: float, h: float, l: float, c: float) -> Bar:\n    return Bar(ds + mod * 60, o, h, l, c)\n\n\ndef build_day(ds: int, tf: int, tf_bars: list) -> list:\n    """tf_bars: list of (o,h,l,c) for consecutive tf bars from 09:15; expands each\n    into tf 1m bars that reproduce exactly that OHLC (open first, then high,\n    low, then close)."""\n    out = []\n    for k, (o, h, l, c) in enumerate(tf_bars):\n        base = SESSION_OPEN_MIN + k * tf\n        # minute 0: open→open, minute 1: to high, minute 2: to low, last: close\n        mins = []\n        for i in range(tf):\n            if i == 0:\n                mins.append((o, o, o, o))\n            elif i == 1:\n                mins.append((o, h, o, h))\n            elif i == 2:\n                mins.append((h, h, l, l))\n            elif i == tf - 1:\n                mins.append((l, max(l, c), min(l, c), c))\n            else:\n                mins.append((l, l, l, l))\n        if tf < 4:  # squeeze all levels into fewer minutes\n            mins = [(o, h, l, c)] + [(c, c, c, c)] * (tf - 1)\n        for i, (a, b, c_, d) in enumerate(mins):\n            out.append(m1(ds, base + i, a, b, c_, d))\n    return out\n\n\ndef part_a() -> None:\n    print("PART A — engine")\n    d = date(2026, 3, 4)\n    ds = ds_of(d)\n    tf = 5\n    # 16 warm-up bars of ~10pt range then an impulse leaving a bull FVG:\n    warm = [(24000 + (i % 3), 24006 + (i % 3), 23996 + (i % 3), 24002 + (i % 3)) for i in range(16)]\n    # c0 (ts index 16): 24000-24010 ; c1 displacement: 24005 → 24060 ; c2: low 24040 > c0.high 24010\n    c0 = (24002, 24010, 23998, 24005)\n    c1 = (24005, 24062, 24004, 24060)\n    c2 = (24060, 24075, 24040, 24070)\n    bars_tf = warm + [c0, c1, c2]\n    bars = build_day(ds, tf, bars_tf)\n    eng = FvgEngine(EngineConfig(), ATR(14))\n    sigs = session_signals(eng, bars, day_start_epoch=ds, tf_minutes=tf)\n    check(eng.diag.get("gap_born_bull", 0) == 1, f"bull FVG born (diag={eng.diag})")\n    g = eng.gaps[0]\n    check(abs(g.top - 24040) < 1e-9 and abs(g.bottom - 24010) < 1e-9, f"zone {g.bottom}-{g.top}")\n    check(g.fib_ok, f"fib gate passes (leg {g.leg_low}-{g.leg_high})")\n    check(sigs == [], "no signal on the birth day so far")\n\n    # next tf bar: minutes dip INTO the zone then a green close back above top\n    nb = SESSION_OPEN_MIN + 19 * tf\n    tail = [m1(ds, nb, 24068, 24070, 24035, 24038),      # touch (low <= top)\n            m1(ds, nb + 1, 24038, 24045, 24030, 24039),  # still inside, green but close<=top\n            m1(ds, nb + 2, 24044, 24052, 24042, 24050),  # green close > top → trigger\n            m1(ds, nb + 3, 24050, 24055, 24048, 24052),\n            m1(ds, nb + 4, 24052, 24058, 24050, 24056)]\n    eng2 = FvgEngine(EngineConfig(), ATR(14))\n    sigs = session_signals(eng2, bars + tail, day_start_epoch=ds, tf_minutes=tf)\n    check(len(sigs) == 1 and sigs[0].side == "CE" and sigs[0].kind == "FVG",\n          f"CE FVG signal fires on the rejection close ({sigs})")\n    if sigs:\n        s = sigs[0]\n        check(s.trigger_min == nb + 2, f"trigger minute {s.trigger_min} == {nb + 2}")\n        check(s.sl_level < 24010 and s.sl_level > 24000, f"stop below zone bottom with ATR buffer ({s.sl_level:.2f})")\n        check(s.leg_target == 24075, f"fib 1.0 target = impulse high ({s.leg_target})")\n    check(eng2.gaps[0].used, "gap consumed after one trigger")\n\n    # direction gate\n    eng3 = FvgEngine(EngineConfig(direction="PE"), ATR(14))\n    check(session_signals(eng3, bars + tail, day_start_epoch=ds, tf_minutes=tf) == [],\n          "direction=PE suppresses the CE setup")\n    # fib gate rejection: the leg\'s swing low sits well below (an extended run\n    # BEFORE the displacement), so the gap lands in the top 38% of the leg\n    warm_b = list(warm)\n    warm_b[10] = (23900, 23905, 23800, 23900)\n    barsb = build_day(ds, tf, warm_b + [c0, c1, c2])\n    eng4 = FvgEngine(EngineConfig(), ATR(14))\n    session_signals(eng4, barsb, day_start_epoch=ds, tf_minutes=tf)\n    check(eng4.gaps and not eng4.gaps[0].fib_ok, "shallow gap (top of the leg) fails the fib gate")\n    eng4b = FvgEngine(EngineConfig(fib_gate=False), ATR(14))\n    session_signals(eng4b, barsb, day_start_epoch=ds, tf_minutes=tf)\n    check(eng4b.gaps and eng4b.gaps[0].fib_ok is False and eng4b.cfg.fib_gate is False,\n          "fib_gate=off keeps the gap tradeable (flag still recorded)")\n\n    # inversion → IFVG: tf bar closes below bottom, then a rally into the band and a red close below it\n    inv = [(24068, 24070, 23990, 23995)]     # close < bottom 24010 → INVERTED (bearish band)\n    bars_inv = build_day(ds, tf, bars_tf + inv)\n    nb2 = SESSION_OPEN_MIN + 20 * tf\n    tail2 = [m1(ds, nb2, 23995, 24015, 23994, 24012),    # high >= bottom → touched\n             m1(ds, nb2 + 1, 24012, 24020, 24000, 24005),  # red close < bottom → PE trigger\n             m1(ds, nb2 + 2, 24005, 24008, 23990, 23992)]\n    eng5 = FvgEngine(EngineConfig(), ATR(14))\n    sigs = session_signals(eng5, bars_inv + tail2, day_start_epoch=ds, tf_minutes=tf)\n    check(eng5.diag.get("gap_inverted", 0) == 1, "bull gap inverted on a tf close below bottom")\n    check(len(sigs) == 1 and sigs[0].side == "PE" and sigs[0].kind == "IFVG",\n          f"IFVG PE signal on the retest rejection ({sigs})")\n    if sigs:\n        check(sigs[0].sl_level > 24040 and sigs[0].leg_target is None,\n              f"IFVG stop above band top, no fib target ({sigs[0].sl_level:.2f})")\n    eng6 = FvgEngine(EngineConfig(trade_ifvg=False), ATR(14))\n    check(session_signals(eng6, bars_inv + tail2, day_start_epoch=ds, tf_minutes=tf) == [],\n          "trade_ifvg=0 suppresses the inverted setup")\n\n    # expiry: gap_max_age tf bars of quiet after birth → dead, no trigger later\n    quiet = [(24060, 24064, 24056, 24060)] * 13\n    late = [m1(ds, SESSION_OPEN_MIN + 32 * tf, 24060, 24061, 24035, 24038),\n            m1(ds, SESSION_OPEN_MIN + 32 * tf + 1, 24038, 24050, 24037, 24049)]\n    eng7 = FvgEngine(EngineConfig(gap_max_age=12), ATR(14))\n    sigs = session_signals(eng7, build_day(ds, tf, bars_tf + quiet) + late, day_start_epoch=ds, tf_minutes=tf)\n    check(eng7.diag.get("gap_expired", 0) == 1 and sigs == [], "gap expires after gap_max_age bars")\n\n    # resample sanity\n    rs = resample_session(bars, day_start_epoch=ds, tf_minutes=tf)\n    check(len(rs) == len(bars_tf) and rs[17].high == 24062 and rs[18].low == 24040,\n          "resample reproduces tf OHLC")\n    # ATR continuity across sessions: warm-up then a new day keeps the value\n    a = ATR(14)\n    for b in rs:\n        a.update(b)\n    v = a.value\n    check(v is not None and v > 0, f"ATR warmed ({v:.2f})")\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  PART B — synthetic corpus, end-to-end\n# ─────────────────────────────────────────────────────────────────────────\ndef _ncdf(x: float) -> float:\n    return 0.5 * (1.0 + math.erf(x / math.sqrt(2)))\n\n\ndef bs(spot: float, k: float, t: float, iv: float, kind: str) -> float:\n    if t <= 0:\n        return max(spot - k, 0.0) if kind == "CE" else max(k - spot, 0.0)\n    d1 = (math.log(spot / k) + 0.5 * iv * iv * t) / (iv * math.sqrt(t))\n    d2 = d1 - iv * math.sqrt(t)\n    if kind == "CE":\n        return spot * _ncdf(d1) - k * _ncdf(d2)\n    return k * _ncdf(-d2) - spot * _ncdf(-d1)\n\n\ndef next_tuesday(d: date) -> date:\n    return d + timedelta(days=(1 - d.weekday()) % 7)\n\n\ndef build_corpus(path: str, sessions: int = 45, seed: int = 7) -> tuple:\n    rnd = random.Random(seed)\n    conn = sqlite3.connect(path)\n    conn.executescript("""\n    CREATE TABLE backtest_candles_1m (\n        instrument_token INTEGER NOT NULL, ts INTEGER NOT NULL, underlying TEXT NOT NULL,\n        tradingsymbol TEXT NOT NULL, instrument_type TEXT NOT NULL, strike REAL NOT NULL,\n        expiry TEXT NOT NULL, open REAL NOT NULL, high REAL NOT NULL, low REAL NOT NULL,\n        close REAL NOT NULL, volume INTEGER NOT NULL DEFAULT 0, oi INTEGER NOT NULL DEFAULT 0,\n        PRIMARY KEY (instrument_token, ts));\n    CREATE INDEX idx_bt1m_sym_ts ON backtest_candles_1m (tradingsymbol, ts);\n    CREATE INDEX idx_bt1m_under_exp_ts ON backtest_candles_1m (underlying, expiry, ts);\n    """)\n    d = date(2026, 1, 5)\n    spot = 24000.0\n    rows = []\n    token = 1000\n    tokens: dict = {}\n    days = []\n    while len(days) < sessions:\n        if d.weekday() >= 5 or d == date(2026, 1, 26):\n            d += timedelta(days=1)\n            continue\n        days.append(d)\n        ds = ds_of(d)\n        exp = next_tuesday(d)\n        exp_iso = exp.isoformat()\n        exp_ts = ds_of(exp) + (15 * 60 + 30) * 60\n        iv = 0.14\n        strikes = None\n        for mod in range(SESSION_OPEN_MIN, 15 * 60 + 30):\n            # regime: random walk with occasional impulses (to create gaps)\n            step = rnd.gauss(0, 3.0)\n            if rnd.random() < 0.02:\n                step += rnd.choice([-1, 1]) * rnd.uniform(25, 60)\n            o = spot\n            c = spot + step\n            h = max(o, c) + abs(rnd.gauss(0, 1.5))\n            l = min(o, c) - abs(rnd.gauss(0, 1.5))\n            spot = c\n            ts = ds + mod * 60\n            rows.append((256265, ts, "NIFTY", "NIFTYSPOT", "SPOT", 0.0, "", o, h, l, c, 0, 0))\n            if strikes is None:\n                atm = round(spot / 50) * 50\n                strikes = [atm + 50 * i for i in range(-8, 9)]\n            t_years = max((exp_ts - ts) / (365.0 * 86400), 1e-6)\n            for k in strikes:\n                for kind in ("CE", "PE"):\n                    sym = f"NIFTY{exp.strftime(\'%y%-m%d\')}{int(k)}{kind}"\n                    if sym not in tokens:\n                        token += 1\n                        tokens[sym] = token\n                    po = max(bs(o, k, t_years, iv, kind), 0.05)\n                    pc = max(bs(c, k, t_years, iv, kind), 0.05)\n                    ph = max(bs(h if kind == "CE" else l, k, t_years, iv, kind), 0.05)\n                    pl = max(bs(l if kind == "CE" else h, k, t_years, iv, kind), 0.05)\n                    rows.append((tokens[sym], ts, "NIFTY", sym, kind, float(k), exp_iso,\n                                 round(po, 2), round(max(ph, po, pc), 2), round(min(pl, po, pc), 2),\n                                 round(pc, 2), 100, 1000))\n        d += timedelta(days=1)\n    conn.executemany("INSERT INTO backtest_candles_1m VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)", rows)\n    conn.commit()\n    conn.close()\n    return days, len(rows)\n\n\ndef part_b() -> None:\n    print("PART B — synthetic corpus, end-to-end")\n    tmp = tempfile.mkdtemp()\n    db = os.path.join(tmp, "backtest.db")\n    days, n = build_corpus(db)\n    print(f"  built {n:,} rows, {len(days)} sessions {days[0]}..{days[-1]}")\n    corpus = bt.Corpus(db, "NIFTY")\n    corpus.load_spot(days[0], days[-1])\n    corpus.load_expiry_ranges()\n    check(len(corpus.spot) == len(days), "spot sessions loaded")\n    check(corpus.front_expiry(days[3]) == next_tuesday(days[3]).isoformat(), "front expiry = next Tuesday with prints")\n    check(corpus.front_expiry(next_tuesday(days[3])) == next_tuesday(days[3]).isoformat(), "expiry day maps to itself")\n\n    cfg = bt.merge_cfg({"lots": 1, "warmup_sessions": 3})\n    res = bt.run(corpus, cfg, days[5], days[-1])\n    tr, dg, sc = res["trades"], res["diag"], res["score"]\n    check(dg["days_total"] == len(days) - 5, f"days iterated {int(dg[\'days_total\'])}")\n    check(len(tr) > 0, f"trades produced: {len(tr)} (signals {int(dg[\'signals_total\'])})")\n    ok = all(t.exit_reason in ("SL", "TP", "TIME", "EOD", "BE") for t in tr)\n    check(ok, "every trade closed with a known reason")\n    check(all(abs(t.net - (t.gross - t.charges)) < 0.02 for t in tr), "net == gross − charges")\n    check(all(t.exit_ts >= t.entry_ts for t in tr), "exit never before entry")\n    check(all(t.hold_min <= cfg["hold_max"] or t.exit_reason == "EOD" for t in tr), "hold_max respected")\n    # no overlapping positions\n    ordered = sorted(tr, key=lambda t: t.entry_ts)\n    check(all(b.entry_ts > a.exit_ts for a, b in zip(ordered, ordered[1:]) if a.date == b.date),\n          "one position at a time")\n    check(all(t.qty == 65 for t in tr), "qty = lots × 65")\n    eod_bad = [t for t in tr if bt._hhmm(t.entry_time) >= bt._hhmm(cfg["entry_until"])]\n    check(not eod_bad, "no entries after entry_until")\n    check(all(t.risk_pts >= cfg["sl_min_pts"] - 1e-9 for t in tr), "risk >= sl_min_pts")\n    check(sc["n_years"] >= 1 and sc["n_months"] >= 1 and sc["max_dd"] >= 0, "scoreboard computed")\n    sl_low = [t for t in tr if t.exit_reason == "SL"]\n    check(all(t.net_alt_fill >= t.net - 1e-6 for t in sl_low), "close-fill alt is never worse than low-fill on SL exits")\n    kinds = {t.kind for t in tr}\n    print(f"  setups seen: {kinds}; exits: { {k: int(v) for k, v in dg.items() if k.endswith(\'_exits\') and v} }")\n    bt.report(res, months=True)\n\n    # variants must run and differ\n    r2 = bt.run(corpus, bt.merge_cfg({"sl_fill": "close", "warmup_sessions": 3}), days[5], days[-1])\n    check(abs(r2["score"]["net"] - sc["net_alt_fill"]) < 1.0,\n          f"sl_fill=close run reproduces net_alt_fill ({r2[\'score\'][\'net\']} vs {sc[\'net_alt_fill\']})")\n    r3 = bt.run(corpus, bt.merge_cfg({"tp_mode": "fib", "warmup_sessions": 3}), days[5], days[-1])\n    check(r3["score"]["trades"] > 0, "tp_mode=fib runs")\n    r4 = bt.run(corpus, bt.merge_cfg({"be_rr": 1.0, "warmup_sessions": 3}), days[5], days[-1])\n    check(r4["diag"]["be_armed"] >= 0, "breakeven variant runs")\n    r5 = bt.run(corpus, bt.merge_cfg({"direction": "PE", "warmup_sessions": 3}), days[5], days[-1])\n    check(all(t.side == "PE" for t in r5["trades"]), "direction=PE yields only PE trades")\n    r6 = bt.run(corpus, bt.merge_cfg({"skip_expiry_day": 1, "warmup_sessions": 3}), days[5], days[-1])\n    check(all(t.dte > 0 for t in r6["trades"]) and r6["diag"]["days_skipped_expiry"] >= 0, "skip_expiry_day drops 0DTE")\n    r7 = bt.run(corpus, bt.merge_cfg({"sl_trigger": "close", "warmup_sessions": 3}), days[5], days[-1])\n    t7 = r7["trades"]\n    check(len(t7) > 0 and r7["score"]["net"] != sc["net"], "sl_trigger=close runs and differs from touch")\n    close_ok = True\n    for t in t7:\n        if t.exit_reason in ("SL", "TP") and t.exit_ts < ds_of(date.fromisoformat(t.date)) + bt._hhmm(cfg["eod_square_off"]) * 60:\n            ob = corpus.option_day(t.tradingsymbol, ds_of(date.fromisoformat(t.date)))\n            o2 = ob.get(t.exit_ts)\n            sp = {(b.ts - ds_of(date.fromisoformat(t.date))) // 60: b for b in corpus.spot[date.fromisoformat(t.date)]}\n            prev = sp.get((t.exit_ts - ds_of(date.fromisoformat(t.date))) // 60 - 1)\n            trig = (prev.close <= t.sl_spot or prev.close >= t.tp_spot) if t.side == "CE" else \\\n                   (prev.close >= t.sl_spot or prev.close <= t.tp_spot)\n            if o2 is None or abs(o2.open - t.exit_price) > 1e-6 or not trig:\n                close_ok = False\n                break\n    check(close_ok, "close-trigger exits fill at the NEXT minute\'s option open after a 1m close through the level")\n    r8 = bt.run(corpus, bt.merge_cfg({"dte_min": 3, "warmup_sessions": 3}), days[5], days[-1])\n    check(r8["trades"] and all(t.dte >= 3 for t in r8["trades"]) and r8["diag"]["days_skipped_dte"] > 0,\n          f"dte_min=3 keeps only 3-4DTE sessions ({len(r8[\'trades\'])} trades, skipped {int(r8[\'diag\'][\'days_skipped_dte\'])} days)")\n    check(abs(sc["net_a"] + sc["net_b"] - sc["net"]) < 0.02, "split-half nets sum to net")\n    rA = bt.run(corpus, bt.merge_cfg({"entry_mode": "fixed", "warmup_sessions": 3, "direction": "CE"}), days[5], days[-1])\n    tA = rA["trades"]\n    check(len(tA) == len(days) - 5 and all(t.kind == "CTRL" and t.entry_time == "10:00" and t.side == "CE" for t in tA),\n          f"control A: one CE entry at 10:00 on every session ({len(tA)})")\n    check(all(abs(t.risk_pts - 30.0) < 1e-9 for t in tA), "control A: fixed 30-pt stop")\n    rB = bt.run(corpus, bt.merge_cfg({"entry_mode": "matched", "warmup_sessions": 3, "direction": "CE"}), days[5], days[-1])\n    rF = bt.run(corpus, bt.merge_cfg({"warmup_sessions": 3, "direction": "CE"}), days[5], days[-1])\n    fvg_days = {t.date for t in rF["trades"]}\n    ctl_days = {t.date for t in rB["trades"]}\n    check(0 < len(ctl_days) <= len(tA) and fvg_days <= ctl_days,\n          f"control B: fixed entries only on FVG-signal days ({len(ctl_days)} days ⊇ {len(fvg_days)} traded)")\n    try:\n        bt.merge_cfg({"nonsense": 1})\n        check(False, "unknown key rejected")\n    except SystemExit:\n        check(True, "unknown key rejected")\n\n    # CLI\n    exp_csv = os.path.join(tmp, "trades.csv")\n    cmd = [sys.executable, os.path.join(HERE, "fvg_fib_backtest.py"), "--db", db,\n           "--from", days[5].isoformat(), "--to", days[-1].isoformat(), "--months",\n           "--export", exp_csv, "--set", "warmup_sessions=3", "tp_rr=2.5"]\n    p = subprocess.run(cmd, capture_output=True, text=True)\n    check(p.returncode == 0 and "SCOREBOARD" in p.stdout, f"CLI single run (rc={p.returncode}) {p.stderr[-300:]}")\n    check(os.path.exists(exp_csv) and sum(1 for _ in open(exp_csv)) > 1, "CSV exported")\n    cmd = [sys.executable, os.path.join(HERE, "fvg_fib_backtest.py"), "--db", db,\n           "--from", days[5].isoformat(), "--to", days[-1].isoformat(),\n           "--grid", "tf=3,5;tp_rr=1.5,3", "--set", "warmup_sessions=3"]\n    p = subprocess.run(cmd, capture_output=True, text=True)\n    check(p.returncode == 0 and "RANKED" in p.stdout and p.stdout.count("\\n  [") == 4,\n          f"CLI grid (4 combos) rc={p.returncode} {p.stderr[-300:]}")\n    print(p.stdout[p.stdout.find("RANKED"):][:900])\n\n\nif __name__ == "__main__":\n    part_a()\n    part_b()\n    print(f"\\n{\'ALL PASS\' if FAILS == 0 else f\'{FAILS} FAILURE(S)\'}")\n    sys.exit(1 if FAILS else 0)\n'}

